// Outermost safety net. The hook body below sets up ~60 top-level statements
// (player profile, runtime settings, store sessions) before dispatch is reached,
// so a failure there cannot be reported through the Status card -- but it must
// still not break the player's turn. Returning the platform's own text is a valid
// result for every hook, and is trivially append-only for contextAppend.
function CharacterContinuity(hook, incomingText) {
  try {
    return characterContinuityHooks(hook, incomingText);
  } catch (error) {
    try {
      log("[Character Continuity Stable] The " + hook + " hook failed before it could report: "
        + (error && error.message ? error.message : error));
    } catch (ignored) {
      // log() is a platform global and may be absent; the pass-through below still holds.
    }
    return typeof incomingText === "string" && incomingText.length ? incomingText : " ";
  }
}


// ----------------------------------------------------------------------------
// v3.1.0 hook orchestration. Slash commands and the shared front-memory note
// live here, outside the continuity engine, so each part fails safe on its own
// and the engine's own logic is untouched.
// Order per hook:
//   Input:   timeline commands → CC input
//   Context: CC context (CC's suffix stays last)
//   Output:  CC output
// ----------------------------------------------------------------------------
const CONTINUITY_FRONT_MEMORY_ORDER = ["timeline"];
const CONTINUITY_TIMER_COMMANDS = ["time", "skip"];

function continuityLog(message) {
  try { log("[Character Continuity Stable] " + message); } catch (ignored) { /* log may be absent */ }
}

// The front-memory note is shared: each owner replaces only its own part and
// any text another script put there is kept in front of it.
function continuityFrontMemoryWrite(owner, text) {
  if (typeof state !== "object" || !state) return;
  if (!state.memory || typeof state.memory !== "object") state.memory = {};
  let store = state.continuityFrontMemory;
  if (!store || typeof store !== "object" || Array.isArray(store)) store = { parts: {}, composed: "" };
  if (!store.parts || typeof store.parts !== "object" || Array.isArray(store.parts)) store.parts = {};
  if (typeof store.composed !== "string") store.composed = "";
  const current = typeof state.memory.frontMemory === "string" ? state.memory.frontMemory : "";
  let foreign = current;
  if (store.composed && foreign.includes(store.composed)) foreign = foreign.replace(store.composed, "");
  foreign = foreign.replace(/\n{3,}/g, "\n\n").trim();
  store.parts[owner] = typeof text === "string" ? text : "";
  const parts = CONTINUITY_FRONT_MEMORY_ORDER.map(key => store.parts[key]).filter(Boolean);
  const composed = parts.length ? "\n" + parts.join("\n") : "";
  const next = foreign + composed;
  if (next !== current) state.memory.frontMemory = next;
  store.composed = composed;
  state.continuityFrontMemory = store;
}

function continuityFrontMemoryPart(owner) {
  const store = typeof state === "object" && state ? state.continuityFrontMemory : null;
  return store && store.parts && typeof store.parts[owner] === "string" ? store.parts[owner] : "";
}

function continuitySettingsCard() {
  const S = CHARACTER_CONTINUITY_STABLE_SETTINGS;
  const list = typeof storyCards !== "undefined" && Array.isArray(storyCards) ? storyCards : [];
  const key = S.CARD_KEY_PREFIX + S.SETTINGS_TITLE;
  let index = list.findIndex(card => card && String(card.title || "").trim() === S.SETTINGS_TITLE);
  if (index < 0) index = list.findIndex(card => card && String(card.keys || "").split(",").some(item => item.trim() === key));
  return index < 0 ? null : { card: list[index], index };
}

function continuityFeatureFlags() {
  const S = CHARACTER_CONTINUITY_STABLE_SETTINGS;
  const flags = { enabled: S.DEFAULT_ENABLED !== false, timeline: S.DEFAULT_TIMELINE !== false };
  try {
    const found = continuitySettingsCard();
    const entry = found && typeof found.card.entry === "string" ? found.card.entry : "";
    const read = (label, fallback) => {
      const match = entry.match(new RegExp("^[ \\t]*" + label + "[ \\t]*:[ \\t]*([^\\r\\n]*?)[ \\t]*$", "im"));
      const value = match ? match[1].toLowerCase() : "";
      if (["true", "yes", "on", "1", "enabled"].includes(value)) return true;
      if (["false", "no", "off", "0", "disabled"].includes(value)) return false;
      return fallback;
    };
    flags.enabled = read("Enabled", flags.enabled);
    flags.timeline = read("Timeline", flags.timeline);
  } catch (error) {
    continuityLog("Could not read CC — Settings: " + (error && error.message ? error.message : error));
  }
  return flags;
}

function continuityHasStory() {
  const list = typeof history !== "undefined" && Array.isArray(history) ? history : [];
  return list.some(item => item && ["continue", "do", "say", "story"].includes(String(item.type)));
}

// Removes the timeline commands (/time, /skip) from the player's input.
function continuityExtractCommands(text) {
  const names = CONTINUITY_TIMER_COMMANDS;
  const pattern = new RegExp("(?<=^|[\\s\"“(])\\/(" + names.join("|") + ")\\b([^\\n\"”/]*)", "gi");
  const commands = [];
  const notices = [];
  let removed = 0;
  const stripped = String(text).replace(pattern, (whole, name, args) => {
    const command = name.toLowerCase();
    const rest = args.trim().replace(/[.!?,;:]+$/, "").trim();
    commands.push({ name: command, args: rest });
    removed += 1;
    return "";
  });
  if (!removed) return { text, commands, notices };
  const leftover = stripped
    .replace(/^\s*>\s*you\s+(?:say\s*)?/i, "")
    .replace(/["“”()]/g, "")
    .replace(/[\s.!?,;:]+/g, "");
  const cleaned = stripped.replace(/[ \t]{2,}/g, " ").replace(/ +([.!?,;])/g, "$1");
  return { text: leftover ? cleaned : " ", commands, notices };
}

function continuityRunEngine(hook, text, extras) {
  try {
    return characterContinuityRun(hook, text, extras);
  } catch (error) {
    continuityLog("The " + hook + " hook failed before it could report: " + (error && error.message ? error.message : error));
    return typeof text === "string" && text.length ? text : " ";
  }
}

function characterContinuityHooks(hook, incomingText) {
  const kind = String(hook || "");
  const original = typeof incomingText === "string" ? incomingText : String(incomingText ?? "");
  const flags = continuityFeatureFlags();
  const clearDisabledParts = () => {
    if (!flags.enabled || !flags.timeline) continuityFrontMemoryWrite("timeline", "");
  };

  if (kind === "input") {
    let text = original;
    let commands = [];
    let notices = [];
    if (continuityHasStory()) {
      const extracted = continuityExtractCommands(text);
      text = extracted.text;
      commands = extracted.commands;
      notices = extracted.notices;
    }
    if (!text || !text.length) text = " ";
    const result = continuityRunEngine("input", text, { commands, notices });
    clearDisabledParts();
    return result && result.length ? result : " ";
  }

  if (kind === "context" || kind === "contextAppend") {
    const appendOnly = kind === "contextAppend";
    const staleTimeline = continuityFrontMemoryPart("timeline");
    let result = continuityRunEngine(kind, original);
    clearDisabledParts();
    // Replaceable context only: a Retry/Undo restore can leave the note the
    // platform assembled one turn ahead; swap in the restored one.
    const freshTimeline = continuityFrontMemoryPart("timeline");
    if (!appendOnly && staleTimeline && freshTimeline && staleTimeline !== freshTimeline && result.includes(staleTimeline)) {
      result = result.replace(staleTimeline, freshTimeline);
    }
    return result;
  }

  if (kind === "output") {
    let result = continuityRunEngine("output", original);
    clearDisabledParts();
    return result && result.length ? result : " ";
  }

  return continuityRunEngine(kind, original);
}

function characterContinuityRun(hook, incomingText, extras) {
  const settings = CHARACTER_CONTINUITY_STABLE_SETTINGS;
  const hookCommands = extras && Array.isArray(extras.commands) ? extras.commands : [];
  const hookNotices = extras && Array.isArray(extras.notices) ? extras.notices : [];
  const originalText = incomingText;
  const appendOnlyContext = hook === "contextAppend";
  const inputHook = hook === "input";
  const contextHook = hook === "context" || hook === "contextAppend";
  const outputHook = hook === "output";
  const rootState = state;
  // The platform normally supplies these, but a missing or malformed global must
  // not take the turn down before the hook body can degrade gracefully.
  const historyList = Array.isArray(history) ? history : [];
  const cards = Array.isArray(storyCards) ? storyCards : [];
  const STORE_KINDS = ["names", "views", "relationships", "turningpoints", "experiences"];
  const storeSession = STORE_KINDS.reduce((result, kind) => {
    result[kind] = {
      loaded: false,
      dirty: false,
      repaired: false,
      projected: false,
      parses: 0,
      writes: 0,
      invalidations: 0,
      lastWrite: "",
      verifying: false,
      verificationFailed: false
    };
    return result;
  }, {});
  const cardTitleCache = new Map();
  const namedTitlePartsCache = new Map();
  const namedCardOwnerCache = new Map();
  const canonicalOutputCache = new Map();
  const canonicalHashCache = new Map();
  const recentStoryCache = new Map();
  const anchorMatchCache = new WeakMap();
  const maintenanceSession = {
    mode: contextHook ? "context-pending" : (inputHook ? "state-sync" : (outputHook ? "lazy-output" : "status-only")),
    structure: "deferred",
    stores: "deferred",
    stateSync: false,
    repaired: [],
    recorded: false
  };
  let cardCatalog = null;
  let finalContextSuffixVerified = false;

  function finish(value) {
    return typeof value === "string" && value.length ? value : " ";
  }

  function debug(message) {
    if (settings.DEBUG_LOGS === true) {
      log("[Character Continuity Stable] " + message);
    }
  }

  function textOf(value) {
    return value === null || value === undefined ? "" : String(value);
  }

  function platformActionCount() {
    const value = Number(typeof info !== "undefined" && info ? info.actionCount : NaN);
    return Number.isFinite(value) && value >= 0 ? Math.floor(value) : null;
  }

  function clean(value, limit) {
    const result = textOf(value)
      .replace(/\r/g, "")
      .replace(/[ \t]+/g, " ")
      .replace(/\n{3,}/g, "\n\n")
      .trim()
      .slice(0, Math.max(1, Number(limit) || 10000));
    return /[\uD800-\uDBFF]$/.test(result) ? result.slice(0, -1) : result;
  }

  function line(value, limit) {
    const result = clean(value, Math.max(limit * 3, limit))
      .replace(/\s*\n\s*/g, " ")
      .trim()
      .slice(0, Math.max(1, Number(limit) || 500));
    return /[\uD800-\uDBFF]$/.test(result) ? result.slice(0, -1) : result;
  }

  function wrappedLine(value, limit) {
    const max = Math.max(4, Number(limit) || 500);
    const source = clean(value, 20000).replace(/\s*\n\s*/g, " ").trim();
    if (source.length <= max) return source;
    const closing = source[0] === "{" && source.endsWith("}")
      ? "}"
      : (source[0] === "[" && source.endsWith("]") ? "]" : "");
    return closing
      ? source.slice(0, max - 2).trimEnd() + " " + closing
      : source.slice(0, max);
  }

  function wholeLine(value, max) {
    const result = clean(value, 20000).replace(/\s*\n\s*/g, " ").trim();
    if (!result) return "";
    const limit = Math.max(0, Number(max) || 0);
    return limit > 0 && result.length > limit ? "" : result;
  }

  function compactLineAtBoundary(value, limit) {
    const supplied = Math.floor(Number(limit) || 0);
    if (supplied <= 0) return "";
    const maximum = Math.max(1, supplied);
    const source = clean(value, 20000).replace(/\s*\n\s*/g, " ").trim();
    if (!source || source.length <= maximum) return source;
    if (maximum === 1) return "…";
    const contentLimit = maximum - 1;
    let clipped = "";
    let segmenterUsed = false;
    try {
      if (typeof Intl === "object" && typeof Intl.Segmenter === "function") {
        segmenterUsed = true;
        const segmenter = new Intl.Segmenter(undefined, { granularity: "grapheme" });
        for (const item of segmenter.segment(source)) {
          if (clipped.length + item.segment.length > contentLimit) break;
          clipped += item.segment;
        }
      }
    } catch { segmenterUsed = false; }
    if (!clipped && !segmenterUsed) {
      for (const point of Array.from(source)) {
        if (clipped.length + point.length > contentLimit) break;
        clipped += point;
      }
    }
    if (!clipped) return "…";
    const minimumBoundary = Math.max(1, Math.floor(contentLimit * 0.55));
    let boundary = -1;
    for (let index = clipped.length - 1; index >= minimumBoundary; index -= 1) {
      if (/\s/.test(clipped[index])) {
        boundary = index;
        break;
      }
    }
    if (boundary > 0) clipped = clipped.slice(0, boundary);
    clipped = clipped.replace(/[\s,;:–—-]+$/g, "").trim();
    return clipped + "…";
  }

  function keyOf(value) {
    return textOf(value)
      .toLowerCase()
      .normalize("NFKD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-z0-9]+/g, " ")
      .trim();
  }

  function nameKeyOf(value) {
    return textOf(value)
      .normalize("NFKC")
      .toLowerCase()
      .replace(/[‘’‛]/g, "'")
      .replace(/[‐‑‒–—―]/g, "-")
      .replace(/[ \t\r\n]+/g, " ")
      .trim();
  }

  function titleKeyOf(value) {
    return nameKeyOf(canonicalOwnedCardTitle(value) || line(value, 220));
  }

  function sameNameForm(left, right) {
    const leftKey = nameKeyOf(left);
    return !!leftKey && leftKey === nameKeyOf(right);
  }

  function escapeRegExp(value) {
    return textOf(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }

  function stripOwnedContextSuffix(value) {
    const begin = escapeRegExp(settings.CONTEXT_SUFFIX_BEGIN);
    const end = escapeRegExp(settings.CONTEXT_SUFFIX_END);
    const legacyBegin = escapeRegExp("<CC_FRONT_MEMORY>");
    const legacyEnd = escapeRegExp("</CC_FRONT_MEMORY>");
    return textOf(value)
      .replace(new RegExp(begin + "[\\s\\S]*?" + end, "g"), "")
      .replace(new RegExp(legacyBegin + "[\\s\\S]*?" + legacyEnd, "g"), "");
  }

  function ownedContextSuffixBlock(instructionText) {
    const instruction = textOf(instructionText).replace(/\r/g, "").trim();
    return instruction
      ? [settings.CONTEXT_SUFFIX_BEGIN, instruction, settings.CONTEXT_SUFFIX_END].join("\n")
      : "";
  }

  // CC transports the current response instruction as an ordinary final suffix
  // in either Context mode; it never reads or writes the protected Plot
  // Essentials / Author's Note / Front Memory container. Replaceable Context
  // also removes legacy tagged CC suffixes before adding the current one.
  function beginContextDelivery(contextValue) {
    const suppliedText = textOf(contextValue);
    const baseText = appendOnlyContext ? suppliedText : stripOwnedContextSuffix(suppliedText);
    return {
      ok: true,
      baseText,
      commit(instructionText, preparedContext = baseText) {
        const suffix = ownedContextSuffixBlock(instructionText);
        const prepared = textOf(preparedContext);
        const alreadyEndsWithSuffix = !!suffix
          && prepared.trimEnd().endsWith(suffix.trimEnd());
        const separator = suffix && prepared && !/\n\s*$/.test(prepared) ? "\n\n" : "";
        const returnedText = alreadyEndsWithSuffix
          ? prepared
          : prepared + separator + suffix;
        const returnedSuffixMatches = suffix
          ? returnedText.trimEnd().endsWith(suffix.trimEnd())
          : returnedText === prepared;
        const appendPrefixMatches = !appendOnlyContext || returnedText.startsWith(suppliedText);
        const ok = returnedSuffixMatches && appendPrefixMatches;
        finalContextSuffixVerified = ok;
        return {
          ok,
          delivered: ok && !!textOf(instructionText).trim(),
          text: ok ? returnedText : suppliedText,
          suffix: ok ? suffix : ""
        };
      }
    };
  }

  function clone(value) {
    try { return JSON.parse(JSON.stringify(value)); } catch { return null; }
  }

  function unique(values, limit) {
    const result = [];
    (Array.isArray(values) ? values : []).forEach(value => {
      const item = line(value, limit);
      if (item && !result.some(existing => keyOf(existing) === keyOf(item))) result.push(item);
    });
    return result;
  }

  function uniqueNameForms(values, limit) {
    const result = [];
    (Array.isArray(values) ? values : []).forEach(value => {
      const item = line(value, limit);
      if (item && !result.some(existing => sameNameForm(existing, item))) result.push(item);
    });
    return result;
  }

  function boolValue(value, fallback) {
    const normalized = keyOf(value);
    if (["true", "yes", "on", "1", "enabled"].includes(normalized)) return true;
    if (["false", "no", "off", "0", "disabled"].includes(normalized)) return false;
    return fallback;
  }

  function numberValue(value, fallback, min, max) {
    const parsed = parseInt(value, 10);
    if (!Number.isFinite(parsed)) return fallback;
    return Math.max(min, Math.min(max, parsed));
  }

  function positiveWhole(value, fallback) {
    const source = textOf(value).trim();
    if (!/^\d+$/.test(source)) return fallback;
    const parsed = Number(source);
    return Number.isSafeInteger(parsed) && parsed > 0 ? parsed : fallback;
  }

  function estimateTokens(value) {
    const source = textOf(value).trim();
    if (!source) return 0;
    const structural = (source.match(/[{}[\]<>\":,\\]/g) || []).length;
    return Math.ceil((Math.max(0, source.length - structural) / 3.25) + (structural / 1.8));
  }

  function hashString(value) {
    const source = textOf(value);
    let hash = 2166136261;
    for (let index = 0; index < source.length; index++) {
      hash ^= source.charCodeAt(index);
      hash = Math.imul(hash, 16777619);
    }
    return (hash >>> 0).toString(16);
  }

  function storeSessionFor(kind) {
    return storeSession[keyOf(kind)] || null;
  }

  function storeIsFresh(kind, value) {
    const session = storeSessionFor(kind);
    return !!(session && session.loaded && !session.dirty && value);
  }

  function recordStoreParse(kind, writesAtStart) {
    const session = storeSessionFor(kind);
    if (!session) return;
    session.loaded = true;
    session.parses += 1;
    session.dirty = session.writes > Math.max(0, Number(writesAtStart) || 0);
  }

  function verifiedStoreAfterParse(kind, currentStore, refresh) {
    const session = storeSessionFor(kind);
    if (!session || !session.dirty || typeof refresh !== "function") return currentStore;
    if (session.verifying) {
      session.verificationFailed = true;
      session.dirty = false;
      return currentStore;
    }
    session.verifying = true;
    const verified = refresh() || currentStore;
    session.verifying = false;
    return verified;
  }

  function markStoreDirty(kind, reason) {
    const session = storeSessionFor(kind);
    if (!session) return;
    session.dirty = true;
    session.repaired = false;
    session.projected = false;
    session.writes += 1;
    session.invalidations += 1;
    session.lastWrite = line(reason, 240);
  }

  function storeKindForManagedTitle(value) {
    const parts = ownedCardTitleParts(value);
    if (!parts) return "";
    if (keyOf(parts.label) === keyOf(settings.NAMES_LABEL)) return "names";
    if ([settings.BURIED_VIEWS_LABEL, settings.VIEWS_LABEL]
      .some(label => keyOf(parts.label) === keyOf(label))) return "views";
    if (keyOf(parts.label) === keyOf(settings.RELATIONSHIPS_LABEL)) return "relationships";
    if (keyOf(parts.label) === keyOf(settings.TURNING_POINTS_LABEL)) return "turningpoints";
    if (keyOf(parts.label) === keyOf(settings.EXPERIENCES_LABEL)) return "experiences";
    return "";
  }

  function markManagedTitlesDirty(values, reason) {
    const kinds = new Set((Array.isArray(values) ? values : [values])
      .map(storeKindForManagedTitle)
      .filter(Boolean));
    kinds.forEach(kind => markStoreDirty(kind, reason));
  }

  function storeSessionSummary() {
    return STORE_KINDS.map(kind => {
      const session = storeSession[kind];
      const unexpected = session.parses > session.writes + 1;
      return kind.charAt(0).toUpperCase() + ":" + session.parses + "p/"
        + session.writes + "w" + (unexpected ? "!" : (session.verificationFailed ? "?" : ""));
    }).join(", ");
  }

  function storeSessionWarnings() {
    return STORE_KINDS.flatMap(kind => {
      const session = storeSession[kind];
      const warnings = [];
      if (session.parses > session.writes + 1) {
        warnings.push(kind + " parsed " + session.parses + " times after " + session.writes
          + " managed write" + (session.writes === 1 ? "" : "s") + " in one " + hook + " hook");
      }
      if (session.verificationFailed) {
        warnings.push(kind + " could not settle its latest managed write after one verification reread; "
          + "the reread state was used for the rest of this " + hook + " hook");
      }
      return warnings;
    }).filter(Boolean);
  }

  function visibleTitleOf(card) {
    if (!card) return "";
    return line(typeof card.title === "string" ? card.title : "", 220);
  }

  function rawVisibleTitleOf(card) {
    return card && typeof card.title === "string" ? card.title : "";
  }

  function entryOf(card) {
    return card && typeof card.entry === "string" ? card.entry : "";
  }

  function notesOf(card) {
    return card && typeof card.description === "string" ? card.description : "";
  }

  function encodedManagedTitle(value) {
    return line(value, 220)
      .replace(/%/g, "%25")
      .replace(/,/g, "%2C");
  }

  function decodedManagedTitle(value) {
    return line(value, 1000)
      .replace(/%2C/gi, ",")
      .replace(/%25/gi, "%")
      .slice(0, 220);
  }

  function managedCardKey(title) {
    const logicalTitle = line(title, 220);
    return logicalTitle ? settings.CARD_KEY_PREFIX + encodedManagedTitle(logicalTitle) : "";
  }

  function managedTitleFromKey(value) {
    const source = textOf(value).trim();
    if (!source.startsWith(settings.CARD_KEY_PREFIX)) return "";
    return decodedManagedTitle(source.slice(settings.CARD_KEY_PREFIX.length));
  }

  // Evidence that CC created this card, rather than a player card whose title
  // merely matches the owned-title shape. A managed key proves CC minted the card;
  // a recognisable CC entry wrapper covers cards whose key was lost but whose body
  // is still one CC authored. The free-text card type is not proof of ownership.
  function cardOwnedByContinuity(card) {
    if (!card) return false;
    // A managed key is proof CC minted the card, and a recognisable CC entry
    // wrapper is proof CC authored its body -- which also covers a CC card whose
    // key a player cleared. The card TYPE is deliberately not proof: "Continuity"
    // is free text a player can set on their own card, and trusting it let a
    // player-authored "Sarah's State" be seized and have its triggers rewritten.
    if (managedTitleFromKey(card.keys)) return true;
    return !!managedTitleFromEntry(card);
  }

  function defaultScriptCardTitle(value) {
    return keyOf(value) === keyOf(settings.SCRIPT_CARD_TITLE);
  }

  const OWNED_CARD_LABELS = [
    settings.OUTER_CHARACTER_LABEL,
    settings.INNER_CHARACTER_LABEL,
    settings.NAMES_LABEL,
    settings.STATE_LABEL,
    settings.RELATIONSHIPS_LABEL,
    settings.TURNING_POINTS_LABEL,
    settings.BURIED_VIEWS_LABEL,
    settings.VIEWS_LABEL,
    settings.EXPERIENCES_LABEL,
    "Identity"
  ];
  const PAGED_OWNED_CARD_LABELS = new Set([
    settings.NAMES_LABEL,
    settings.RELATIONSHIPS_LABEL,
    settings.TURNING_POINTS_LABEL,
    settings.BURIED_VIEWS_LABEL,
    settings.VIEWS_LABEL,
    settings.EXPERIENCES_LABEL
  ].map(keyOf));
  const OWNED_CARD_LABEL_PATTERN = OWNED_CARD_LABELS
    .slice()
    .sort((left, right) => right.length - left.length)
    .map(escapeRegExp)
    .join("|");
  const POSSESSIVE_OWNED_TITLE = new RegExp(
    "^(.+?)['’]s\\s+(" + OWNED_CARD_LABEL_PATTERN + ")(?:\\s+(\\d+))?$",
    "i"
  );
  const LEGACY_OWNED_TITLE = new RegExp(
    "^(.+?)\\s+(?:—|–|-)\\s+(" + OWNED_CARD_LABEL_PATTERN + ")(?:\\s+(\\d+))?$",
    "i"
  );

  function canonicalOwnedLabel(value) {
    const normalized = keyOf(value);
    return OWNED_CARD_LABELS.find(label => keyOf(label) === normalized) || "";
  }

  function ownedCardTitle(name, label, page = 1) {
    const owner = line(name, 120);
    const canonicalLabel = canonicalOwnedLabel(label);
    const pageNumber = Number(page) || 1;
    if (!owner || !canonicalLabel || !Number.isSafeInteger(pageNumber) || pageNumber < 1) return "";
    if (pageNumber > 1 && !PAGED_OWNED_CARD_LABELS.has(keyOf(canonicalLabel))) return "";
    if (keyOf(canonicalLabel) === "identity" && !sameNameForm(owner, "Player")) return "";
    return owner + "'s " + canonicalLabel + (pageNumber > 1 ? " " + pageNumber : "");
  }

  function ownedCardTitleParts(value) {
    const source = line(value, 260);
    const possessive = source.match(POSSESSIVE_OWNED_TITLE);
    const legacy = possessive ? null : source.match(LEGACY_OWNED_TITLE);
    const match = possessive || legacy;
    if (!match) return null;
    const owner = line(match[1], 120);
    const label = canonicalOwnedLabel(match[2]);
    const suppliedPage = !!match[3];
    const page = suppliedPage ? Number(match[3]) : 1;
    if (!owner || !label || !Number.isSafeInteger(page) || page < 1
      || (suppliedPage && page === 1)
      || (suppliedPage && !PAGED_OWNED_CARD_LABELS.has(keyOf(label)))
      || (keyOf(label) === "identity" && !sameNameForm(owner, "Player"))) {
      return null;
    }
    return {
      owner,
      label,
      page,
      legacy: !!legacy,
      title: ownedCardTitle(owner, label, page)
    };
  }

  function canonicalOwnedCardTitle(value) {
    const parts = ownedCardTitleParts(value);
    return parts ? parts.title : "";
  }

  function settingTitleFromEntry(card) {
    const match = entryOf(card).match(/^\s*\{\s*Setting['\u2019]s\s+(Scene|Timeline|Event\s+Countdowns)\s*:/i);
    if (!match) return "";
    const kind = match[1].toLowerCase().replace(/\s+/g, " ");
    return kind === "scene" ? "Setting's Scene" : (kind === "timeline" ? settings.TIMELINE_TITLE : settings.COUNTDOWNS_TITLE);
  }

  function managedTitleFromEntry(card) {
    const source = entryOf(card).replace(/\r/g, "");
    if (!source.trim()) return "";
    const settingTitle = settingTitleFromEntry(card);
    if (settingTitle) return settingTitle;

    const profile = source.match(
      /^\s*\{\s*(.+?)['’]s\s+(Outer|Inner)\s*:/i
    );
    if (profile) {
      const label = keyOf(profile[2]) === "outer"
        ? settings.OUTER_CHARACTER_LABEL
        : settings.INNER_CHARACTER_LABEL;
      return ownedCardTitle(profile[1], label);
    }

    const stateProfile = source.match(
      /^\s*\{\s*(.+?)['’]s\s+current\s+private\s+State\s*:/i
    );
    if (stateProfile) {
      return ownedCardTitle(stateProfile[1], settings.STATE_LABEL);
    }

    const headers = source.split("\n")
      .map(row => row.trim())
      .filter(row => row && row !== "{" && row !== "}")
      .slice(0, 4);
    if (headers.includes("Active NPC slots:")) return settings.ACTIVE_NPCS_TITLE;

    for (const header of headers) {
      const paged = header.match(
        /^(.+?)['’]s\s+(Buried Views|Views|Names|Relationships|Turning Points)(?:\s+(\d+))?\s*:\s*$/i
      );
      if (paged) {
        const owner = line(paged[1], 120);
        const normalizedLabel = keyOf(paged[2]);
        const label = normalizedLabel === "buried views"
          ? settings.BURIED_VIEWS_LABEL
          : (normalizedLabel === "views"
            ? settings.VIEWS_LABEL
            : (normalizedLabel === "names"
              ? settings.NAMES_LABEL
              : (normalizedLabel === "turning points"
                ? settings.TURNING_POINTS_LABEL
                : settings.RELATIONSHIPS_LABEL)));
        const page = paged[3] ? Number(paged[3]) : 1;
        return ownedCardTitle(owner, label, page);
      }

      const experiences = header.match(
        /^(.+?)['’]s\s+Experiences(?:\s+(\d+))?\s*:\s*$/i
      );
      if (experiences) {
        const page = experiences[2] ? Number(experiences[2]) : 1;
        return ownedCardTitle(experiences[1], settings.EXPERIENCES_LABEL, page);
      }
    }

    if (hasSettingsField(source, "Enabled")
      && hasSettingsField(source, "Continuity budget")
      && hasSettingsField(source, "State lifetime")) {
      return settings.SETTINGS_TITLE;
    }
    return "";
  }

  function titleOf(card) {
    if (!card) return "";
    const rawKeys = card.keys;
    const rawTitle = card.title;
    const rawEntry = card.entry;
    const cached = cardTitleCache.get(card);
    if (cached
      && cached.keys === rawKeys
      && cached.title === rawTitle
      && cached.entry === rawEntry) {
      return cached.value;
    }
    const managedTitle = managedTitleFromKey(card.keys);
    const visibleTitle = managedTitle ? "" : visibleTitleOf(card);
    const entryTitle = managedTitle || (visibleTitle && !defaultScriptCardTitle(visibleTitle))
      ? ""
      : managedTitleFromEntry(card);
    const resolved = managedTitle
      || (visibleTitle && !defaultScriptCardTitle(visibleTitle) ? visibleTitle : "")
      || entryTitle
      || line(card.keys, 220)
      || visibleTitle;
    const value = canonicalOwnedCardTitle(resolved) || resolved;
    cardTitleCache.set(card, {
      keys: rawKeys,
      title: rawTitle,
      entry: rawEntry,
      value
    });
    return value;
  }

  function invalidateCardCatalog() {
    cardCatalog = null;
  }

  function catalogAppend(map, key, value) {
    if (!key) return;
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(value);
  }

  function currentCardCatalog() {
    if (cardCatalog) return cardCatalog;
    const catalog = {
      records: [],
      indexByCard: new Map(),
      byTitle: new Map(),
      byRawKey: new Map(),
      byId: new Map(),
      namedLabels: new Map(),
      pagedLabels: new Map(),
      experienceOwners: null
    };
    cards.forEach((card, index) => {
      if (!card) return;
      const title = titleOf(card);
      const record = {
        card,
        index,
        title,
        titleKey: titleKeyOf(title),
        rawKey: textOf(card.keys).trim(),
        id: card.id === null || card.id === undefined ? "" : textOf(card.id)
      };
      catalog.records.push(record);
      catalog.indexByCard.set(card, index);
      catalogAppend(catalog.byTitle, record.titleKey, record);
      catalogAppend(catalog.byRawKey, record.rawKey, record);
      catalogAppend(catalog.byId, record.id, record);
    });
    cardCatalog = catalog;
    return catalog;
  }

  function catalogRecordsByTitle(title) {
    return (currentCardCatalog().byTitle.get(titleKeyOf(title)) || []).slice();
  }

  function catalogRecordsByRawKey(value) {
    return (currentCardCatalog().byRawKey.get(textOf(value).trim()) || []).slice();
  }

  function firstCatalogCard(records) {
    const ordered = (Array.isArray(records) ? records : [])
      .filter(record => record && record.card)
      .sort((left, right) => left.index - right.index);
    return ordered.length ? ordered[0].card : null;
  }

  function catalogNamedLabel(label) {
    const catalog = currentCardCatalog();
    const labelKey = keyOf(label);
    if (catalog.namedLabels.has(labelKey)) return catalog.namedLabels.get(labelKey);
    const index = { records: [], byOwner: new Map() };
    catalog.records.forEach(record => {
      const owner = nameFromNamedTitle(record.title, label);
      if (!owner) return;
      const item = { ...record, owner, ownerKey: nameKeyOf(owner) };
      index.records.push(item);
      catalogAppend(index.byOwner, item.ownerKey, item);
    });
    catalog.namedLabels.set(labelKey, index);
    return index;
  }

  function catalogNamedCards(name, label) {
    const records = catalogNamedLabel(label).byOwner.get(nameKeyOf(name)) || [];
    return records.map(record => record.card);
  }

  function catalogNamedOwners(label) {
    return catalogNamedLabel(label).records.map(record => record.owner);
  }

  function catalogPagedLabel(label) {
    const catalog = currentCardCatalog();
    const labelKey = keyOf(label);
    if (catalog.pagedLabels.has(labelKey)) return catalog.pagedLabels.get(labelKey);
    const index = { records: [], byOwner: new Map() };
    catalog.records.forEach(record => {
      const parts = numberedNamedTitleParts(record.title, label);
      if (!parts) return;
      const item = {
        ...record,
        owner: parts.owner,
        ownerKey: nameKeyOf(parts.owner),
        page: parts.page
      };
      index.records.push(item);
      catalogAppend(index.byOwner, item.ownerKey, item);
    });
    index.records.sort((left, right) => left.index - right.index);
    index.byOwner.forEach(records => records.sort((left, right) =>
      left.page - right.page || left.index - right.index
    ));
    catalog.pagedLabels.set(labelKey, index);
    return index;
  }

  function catalogPagedCards(name, label) {
    return (catalogPagedLabel(label).byOwner.get(nameKeyOf(name)) || [])
      .map(record => ({ card: record.card, page: record.page }));
  }

  function catalogCardOrder(card) {
    const index = currentCardCatalog().indexByCard.get(card);
    return Number.isInteger(index) ? index : -1;
  }

  function restoreVisibleCardTitle(card, intendedTitle) {
    const logicalTitle = line(intendedTitle, 220);
    if (!card || !logicalTitle) return card;
    try {
      const priorTitle = card.title;
      card.title = logicalTitle;
      if (priorTitle !== card.title) invalidateCardCatalog();
    } catch (error) {
      debug("Could not restore the visible Story Card title " + logicalTitle + ": " + error.message);
    }
    return card;
  }

  function restoreRawVisibleCardTitle(card, intendedTitle) {
    if (!card) return card;
    const exactTitle = textOf(intendedTitle);
    try {
      const priorTitle = rawVisibleTitleOf(card);
      card.title = exactTitle;
      if (priorTitle !== rawVisibleTitleOf(card)) invalidateCardCatalog();
    } catch (error) {
      debug("Could not restore the exact visible Story Card title: " + error.message);
    }
    return card;
  }

  function restoreCardNotes(card, intendedNotes) {
    if (!card) return card;
    const notes = textOf(intendedNotes);
    try {
      card.description = notes;
    } catch (error) {
      debug("Could not restore the Story Card notes: " + error.message);
    }
    return card;
  }

  function managedCardIdentityMatches(card, intendedTitle) {
    const logicalTitle = line(intendedTitle || titleOf(card), 220);
    return !!(card && logicalTitle
      && textOf(card.keys).trim() === managedCardKey(logicalTitle)
      && titleKeyOf(visibleTitleOf(card)) === titleKeyOf(logicalTitle));
  }

  function exactCardFieldsMatch(card, keys, entry, type, intendedTitle, exactVisibleTitle = false) {
    const suppliedTitle = textOf(intendedTitle);
    const logicalTitle = line(suppliedTitle, 220);
    return !!(card
      && textOf(card.keys) === textOf(keys)
      && entryOf(card) === textOf(entry)
      && textOf(card.type) === textOf(type)
      && (exactVisibleTitle
        ? rawVisibleTitleOf(card) === suppliedTitle
        : (!logicalTitle || titleKeyOf(visibleTitleOf(card)) === titleKeyOf(logicalTitle))));
  }

  function physicalCardPresent(card) {
    if (!card) return false;
    if (cards.includes(card)) return true;
    const id = card.id === null || card.id === undefined ? "" : textOf(card.id);
    return !!(id && cards.some(candidate => candidate
      && candidate.id !== null && candidate.id !== undefined
      && textOf(candidate.id) === id));
  }

  function uniqueCards(values) {
    const result = [];
    (Array.isArray(values) ? values : []).forEach(card => {
      if (card && !result.includes(card)) result.push(card);
    });
    return result;
  }

  function physicalCardId(card) {
    return card && card.id !== null && card.id !== undefined
      ? textOf(card.id)
      : "";
  }

  function exactCardImage(card, index, idOccurrence, imageOccurrence) {
    return {
      card,
      index,
      id: physicalCardId(card),
      idOccurrence,
      imageOccurrence,
      visibleTitle: rawVisibleTitleOf(card),
      keys: textOf(card && card.keys),
      entry: entryOf(card),
      type: textOf(card && card.type)
    };
  }

  function exactCardImageKey(value) {
    const card = value && value.card ? value.card : value;
    return JSON.stringify([
      physicalCardId(card),
      rawVisibleTitleOf(card),
      textOf(card && card.keys),
      entryOf(card),
      textOf(card && card.type)
    ]);
  }

  function capturePhysicalCardDeck() {
    const idCounts = Object.create(null);
    const imageCounts = Object.create(null);
    return cards.map((card, index) => {
      const id = physicalCardId(card);
      const imageKey = exactCardImageKey(card);
      const idOccurrence = idCounts[id] || 0;
      const imageOccurrence = imageCounts[imageKey] || 0;
      idCounts[id] = idOccurrence + 1;
      imageCounts[imageKey] = imageOccurrence + 1;
      return exactCardImage(card, index, idOccurrence, imageOccurrence);
    });
  }

  function exactCardMatchesImage(card, image) {
    return !!(card && image
      && physicalCardId(card) === image.id
      && rawVisibleTitleOf(card) === image.visibleTitle
      && textOf(card.keys) === image.keys
      && entryOf(card) === image.entry
      && textOf(card.type) === image.type);
  }

  function resolvePhysicalCardImage(image, used, allowIndexFallback = false) {
    if (!image) return null;
    const unavailable = used instanceof Set ? used : new Set();
    if (image.card && cards.includes(image.card) && !unavailable.has(image.card)) {
      return image.card;
    }
    if (image.id) {
      const matches = cards.filter(card => physicalCardId(card) === image.id
        && !unavailable.has(card));
      if (matches.length === 1) return matches[0];
      const exactMatches = matches.filter(card => exactCardMatchesImage(card, image));
      if (exactMatches.length === 1) return exactMatches[0];
      if (exactMatches[image.idOccurrence]) return exactMatches[image.idOccurrence];
      return null;
    }
    const imageKey = JSON.stringify([
      image.id, image.visibleTitle, image.keys, image.entry, image.type
    ]);
    const exactMatches = cards.filter(card => exactCardImageKey(card) === imageKey
      && !unavailable.has(card));
    if (exactMatches[image.imageOccurrence]) return exactMatches[image.imageOccurrence];
    if (exactMatches.length === 1) return exactMatches[0];
    if (allowIndexFallback) {
      const indexed = cards[image.index] || null;
      if (indexed && !unavailable.has(indexed)) return indexed;
    }
    return null;
  }

  function mapPhysicalCardImages(images, allowIndexFallback = false) {
    const used = new Set();
    const mapped = (Array.isArray(images) ? images : []).map(image => {
      const card = resolvePhysicalCardImage(image, used, allowIndexFallback);
      if (card) used.add(card);
      return { image, card };
    });
    const unresolvedById = Object.create(null);
    mapped.forEach(item => {
      if (item.card) return;
      const id = item.image.id;
      if (!unresolvedById[id]) unresolvedById[id] = [];
      unresolvedById[id].push(item);
    });
    Object.keys(unresolvedById).forEach(id => {
      const desired = unresolvedById[id];
      const candidates = cards.filter(card => physicalCardId(card) === id && !used.has(card));
      if (desired.length !== candidates.length) return;
      desired.sort((left, right) => left.image.index - right.image.index);
      candidates.sort((left, right) => cards.indexOf(left) - cards.indexOf(right));
      desired.forEach((item, index) => {
        item.card = candidates[index];
        used.add(candidates[index]);
      });
    });
    return { mapped, used, complete: mapped.every(item => !!item.card) };
  }

  function physicalDeckImageMultisetMatches(images) {
    const expected = (Array.isArray(images) ? images : []).map(image => JSON.stringify([
      image.id, image.visibleTitle, image.keys, image.entry, image.type
    ])).sort();
    const actual = cards.map(card => exactCardImageKey(card)).sort();
    return expected.length === actual.length
      && expected.every((value, index) => value === actual[index]);
  }

  function createExactCardImage(image) {
    const prior = capturePhysicalCardDeck();
    const cleanup = () => {
      const mapping = mapPhysicalCardImages(prior, false);
      if (!mapping.complete) return false;
      const additions = cards.filter(card => !mapping.used.has(card));
      additions.slice().sort((left, right) => cardIndex(right) - cardIndex(left))
        .forEach(card => { removeCard(card); });
      return physicalDeckImageMultisetMatches(prior);
    };
    try {
      addStoryCard(image.keys, image.entry, image.type);
      invalidateCardCatalog();
      const mapping = mapPhysicalCardImages(prior, true);
      if (!mapping.complete) {
        cleanup();
        return null;
      }
      const additions = cards.filter(card => !mapping.used.has(card));
      if (cards.length !== prior.length + 1 || additions.length !== 1) {
        cleanup();
        return null;
      }
      const created = restoreRawVisibleCardTitle(additions[0], image.visibleTitle);
      if (exactCardMatchesImage(created, image)) return created;
      cleanup();
      return null;
    } catch (error) {
      debug("Could not recreate an exact Story Card image: " + error.message);
      cleanup();
      return null;
    }
  }

  function restorePhysicalCardDeck(images) {
    const desired = Array.isArray(images) ? images : [];
    let mapping = mapPhysicalCardImages(desired, false);
    let extras = cards.filter(card => !mapping.used.has(card));
    if (mapping.complete) {
      extras.slice().sort((left, right) => cardIndex(right) - cardIndex(left))
        .forEach(card => { removeCard(card); });
    }
    mapping = mapPhysicalCardImages(desired, false);
    for (const item of mapping.mapped) {
      let card = item.card;
      if (!card) {
        if (item.image.id) continue;
        card = createExactCardImage(item.image);
        if (!card) continue;
      }
      if (!exactCardMatchesImage(card, item.image)) {
        const index = cardIndex(card);
        if (index < 0) continue;
        try {
          updateStoryCard(index, item.image.keys, item.image.entry, item.image.type);
          invalidateCardCatalog();
        } catch (error) {
          debug("Could not restore an exact Story Card image: " + error.message);
        }
        const used = new Set();
        card = resolvePhysicalCardImage(item.image, used, false) || card;
      }
      restoreRawVisibleCardTitle(card, item.image.visibleTitle);
    }
    invalidateCardCatalog();
    return physicalDeckImageMultisetMatches(desired);
  }

  function managedCardMatches(title) {
    const logicalTitle = line(title, 220);
    const wantedKey = managedCardKey(logicalTitle);
    return uniqueCards(
      catalogRecordsByTitle(logicalTitle).map(record => record.card)
        .concat(wantedKey ? catalogRecordsByRawKey(wantedKey).map(record => record.card) : [])
    );
  }

  function findCard(title) {
    const wantedKey = managedCardKey(title);
    const matches = catalogRecordsByTitle(title)
      .concat(wantedKey ? catalogRecordsByRawKey(wantedKey) : []);
    return firstCatalogCard(matches);
  }

  function cardIndex(card) {
    if (!card) return -1;
    const catalog = currentCardCatalog();
    const direct = catalog.indexByCard.get(card);
    if (Number.isInteger(direct)) return direct;
    const id = card.id === null || card.id === undefined ? "" : textOf(card.id);
    const idMatches = id ? (catalog.byId.get(id) || []) : [];
    const candidate = idMatches.length === 1 ? firstCatalogCard(idMatches) : null;
    const match = candidate && exactCardImageKey(candidate) === exactCardImageKey(card)
      ? candidate
      : null;
    return match ? catalog.indexByCard.get(match) : -1;
  }

  function extractLine(source, label) {
    const match = textOf(source).match(new RegExp(
      "^[ \\t]*(?:[\\{\\[][ \\t]*)?" + escapeRegExp(label)
      + "[ \\t]*:[ \\t]*([^\\r\\n]*?)[ \\t]*(?:[\\}\\]][ \\t]*)?$",
      "im"
    ));
    return match ? line(match[1], 2000) : "";
  }

  function updateCardAt(index, keys, entry, type, intendedTitle, preserveExactFields = false) {
    if (!Number.isInteger(index) || index < 0 || index >= cards.length) return null;
    const current = cards[index];
    const priorTitle = line(titleOf(current), 220);
    const logicalTitle = line(intendedTitle || priorTitle, 220);
    const nextKeys = preserveExactFields
      ? textOf(keys)
      : (textOf(keys).trim()
        ? textOf(keys)
        : (textOf(current && current.keys).trim()
          ? textOf(current.keys)
          : managedCardKey(logicalTitle)));
    const nextEntry = typeof entry === "string" ? entry : entryOf(current);
    const nextType = preserveExactFields
      ? textOf(type)
      : (textOf(type).trim()
        ? textOf(type)
        : (textOf(current && current.type).trim() ? textOf(current.type) : settings.CARD_TYPE));
    if (textOf(current && current.keys) === nextKeys
      && entryOf(current) === nextEntry
      && textOf(current && current.type) === nextType) {
      const unchanged = restoreVisibleCardTitle(current, logicalTitle);
      return exactCardFieldsMatch(unchanged, nextKeys, nextEntry, nextType, logicalTitle)
        ? unchanged
        : null;
    }
    // Captured only once a write will actually be attempted. capturePhysicalCardDeck
    // JSON-stringifies every card entry in the deck, and the no-op branch above is
    // the common case: readRuntime, the title/wrapper migrations and every store
    // parser re-save unchanged cards to assert identity. Capturing before that
    // check paid a full-deck serialisation per identity re-assert.
    const priorDeck = capturePhysicalCardDeck();
    const targetImage = priorDeck[index];
    const restorePrior = () => restorePhysicalCardDeck(priorDeck);
    const verifiedUpdatedCard = () => {
      if (cards.length !== priorDeck.length) return null;
      const mapping = mapPhysicalCardImages(priorDeck, false);
      let updated = mapping.mapped[index] && mapping.mapped[index].card;
      if (!updated) {
        const fallback = mapPhysicalCardImages(priorDeck, true);
        updated = fallback.mapped[index] && fallback.mapped[index].card;
        if (!fallback.complete) return null;
      } else if (!mapping.complete) {
        return null;
      }
      for (let position = 0; position < priorDeck.length; position += 1) {
        const item = mapping.mapped[position];
        if (position === index) continue;
        if (!item || !exactCardMatchesImage(item.card, item.image)) return null;
      }
      return exactCardFieldsMatch(updated, nextKeys, nextEntry, nextType, logicalTitle)
        ? updated
        : null;
    };
    try {
      updateStoryCard(index, nextKeys, nextEntry, nextType);
      invalidateCardCatalog();
      const resolved = resolvePhysicalCardImage(targetImage, new Set(), false);
      const updated = restoreVisibleCardTitle(resolved, logicalTitle);
      const verified = updated && verifiedUpdatedCard();
      if (!verified) {
        const restored = restorePrior();
        if (!restored) {
          markManagedTitlesDirty(
            [priorTitle, logicalTitle],
            "Incomplete write and rollback for " + (logicalTitle || priorTitle || "managed Story Card")
          );
        }
        debug("Rejected an incomplete Story Card write for "
          + (logicalTitle || priorTitle || nextKeys) + (restored ? "." : "; rollback was incomplete."));
        return null;
      }
      markManagedTitlesDirty(
        [priorTitle, logicalTitle],
        "Updated " + (logicalTitle || priorTitle || "managed Story Card")
      );
      return verified;
    } catch (error) {
      const restored = restorePrior();
      if (!restored) {
        markManagedTitlesDirty(
          [priorTitle, logicalTitle],
          "Failed write and rollback for " + (logicalTitle || priorTitle || "managed Story Card")
        );
      }
      debug("Could not update " + (titleOf(current) || nextKeys) + " through the Story Card API: " + error.message);
      return null;
    }
  }

  function saveCard(card, entry, intendedTitle) {
    const index = cardIndex(card);
    if (index < 0) return null;
    const current = cards[index] || card;
    const logicalTitle = line(intendedTitle || titleOf(current), 220);
    if (!logicalTitle) return null;
    return updateCardAt(
      index,
      managedCardKey(logicalTitle),
      entry,
      settings.CARD_TYPE,
      logicalTitle
    );
  }

  function addCardExact(title, keys, entry, type, notes = "") {
    const cardTitle = line(title, 220);
    if (!cardTitle) return null;
    const cardKey = textOf(keys);
    const cardEntry = typeof entry === "string" ? entry : "";
    const cardType = textOf(type);
    const cardNotes = textOf(notes);
    const priorDeck = capturePhysicalCardDeck();
    const before = priorDeck.length;
    let created = null;
    try {
      const returned = addStoryCard(
        cardKey,
        cardEntry,
        cardType,
        cardTitle,
        cardNotes,
        { returnCard: true }
      );
      invalidateCardCatalog();
      const mapping = mapPhysicalCardImages(priorDeck, false);
      const additions = cards.filter(card => card && !mapping.used.has(card));
      if (returned && typeof returned === "object" && cards.includes(returned)) created = returned;
      else if (mapping.complete && additions.length === 1) created = additions[0];
      created = restoreVisibleCardTitle(created, cardTitle);
      created = restoreCardNotes(created, cardNotes);
      if (cards.length !== before + 1
        || !mapping.complete
        || mapping.mapped.some(item => !exactCardMatchesImage(item.card, item.image))
        || !exactCardFieldsMatch(created, cardKey, cardEntry, cardType, cardTitle)
        || notesOf(created) !== cardNotes) {
        const restored = restorePhysicalCardDeck(priorDeck);
        debug("Rejected an incomplete Story Card creation for " + cardTitle
          + (restored ? "." : "; cleanup was incomplete."));
        return null;
      }
    } catch (error) {
      debug("Could not create " + cardTitle + ": " + error.message);
      const restored = restorePhysicalCardDeck(priorDeck);
      if (!restored) debug("Creation cleanup was incomplete for " + cardTitle + ".");
      return null;
    }
    markManagedTitlesDirty(cardTitle, "Added " + cardTitle);
    return created;
  }

  function addCard(title, entry, notes = "") {
    const cardTitle = line(title, 220);
    if (!cardTitle) return null;
    const cardKey = managedCardKey(cardTitle);
    const cardEntry = typeof entry === "string" ? entry : "";
    const cardNotes = textOf(notes);
    const matching = managedCardMatches(cardTitle);
    if (matching.length > 1) return null;
    if (matching.length === 1) {
      const existing = matching[0];
      if (textOf(existing.keys) !== cardKey || entryOf(existing) !== cardEntry
        || textOf(existing.type) !== settings.CARD_TYPE) return null;
      const restored = restoreVisibleCardTitle(existing, cardTitle);
      if (cardNotes && !notesOf(restored)) restoreCardNotes(restored, cardNotes);
      return exactCardFieldsMatch(
        restored, cardKey, cardEntry, settings.CARD_TYPE, cardTitle
      ) ? restored : null;
    }
    return addCardExact(cardTitle, cardKey, cardEntry, settings.CARD_TYPE, cardNotes);
  }

  function upsertCard(title, entry) {
    const matching = managedCardMatches(title);
    if (matching.length > 1) return null;
    const card = matching[0] || null;
    return card ? saveCard(card, entry) : addCard(title, entry);
  }

  function removeCard(card) {
    const index = cardIndex(card);
    if (index < 0) return false;
    const priorDeck = capturePhysicalCardDeck();
    const target = cards[index] || card;
    const removedTitle = titleOf(target);
    const before = cards.length;
    try {
      removeStoryCard(index);
      invalidateCardCatalog();
      const expected = priorDeck.filter((item, position) => position !== index);
      if (cards.length !== before - 1 || cards.includes(target)
        || !physicalDeckImageMultisetMatches(expected)) {
        const restored = restorePhysicalCardDeck(priorDeck);
        debug("Story Card removal could not be verified for "
          + (removedTitle || "the requested card")
          + (restored ? "." : "; rollback was incomplete."));
        return false;
      }
      markManagedTitlesDirty(removedTitle, "Removed " + (removedTitle || "managed Story Card"));
      return true;
    } catch (error) {
      const restored = restorePhysicalCardDeck(priorDeck);
      debug("Could not remove " + (titleOf(card) || "Story Card") + ": " + error.message);
      if (!restored) debug("Removal rollback was incomplete for " + (removedTitle || "Story Card") + ".");
      return false;
    }
  }

  function removeCards(cardList) {
    const targets = [];
    (Array.isArray(cardList) ? cardList : []).forEach(card => {
      if (card && cardIndex(card) >= 0 && !targets.includes(card)) targets.push(card);
    });
    targets.sort((left, right) => cardIndex(right) - cardIndex(left));
    if (!targets.length) return true;
    let removed = true;
    targets.forEach(card => { if (!removeCard(card)) removed = false; });
    return removed;
  }

  function namedTitle(name, label) {
    return ownedCardTitle(name, label);
  }

  function nameFromNamedTitle(title, label) {
    const cacheKey = textOf(label) + "\u241f" + textOf(title);
    if (namedCardOwnerCache.has(cacheKey)) return namedCardOwnerCache.get(cacheKey);
    const parts = ownedCardTitleParts(title);
    const owner = parts && parts.page === 1 && keyOf(parts.label) === keyOf(label)
      ? parts.owner
      : "";
    namedCardOwnerCache.set(cacheKey, owner);
    return owner;
  }

  function namedCards(name, label) {
    return catalogNamedCards(name, label);
  }

  function namedCard(name, label) {
    return catalogNamedCards(name, label)[0] || null;
  }

  const titleMigrationDiagnostics = [];
  const wrapperMigrationDiagnostics = [];

  function ownedEntryWrapperInfo(value, owner, headerLabel) {
    const source = textOf(value).replace(/\r/g, "");
    const rows = source.split("\n");
    const nonempty = rows.map((row, index) => ({ index, value: row.trim() }))
      .filter(item => item.value);
    const result = {
      source,
      rows,
      valid: false,
      combined: false,
      openingIndex: -1,
      headerIndex: -1,
      closingIndex: -1
    };
    if (nonempty.length < 3 || nonempty[nonempty.length - 1].value !== "}") return result;
    const wantedOwner = line(owner, 120);
    const wantedLabel = line(headerLabel, 120);
    if (!wantedOwner || !wantedLabel) return result;
    const combined = nonempty[0].value.match(
      /^\{\s*(.+?)['’]s\s+(.+?)\s*:\s*$/i
    );
    if (combined
      && sameNameForm(combined[1], wantedOwner)
      && keyOf(combined[2]) === keyOf(wantedLabel)) {
      return {
        ...result,
        valid: true,
        combined: true,
        openingIndex: nonempty[0].index,
        headerIndex: nonempty[0].index,
        closingIndex: nonempty[nonempty.length - 1].index
      };
    }
    if (nonempty[0].value !== "{") return result;
    const split = nonempty[1].value.match(
      /^(.+?)['’]s\s+(.+?)\s*:\s*$/i
    );
    if (!split
      || !sameNameForm(split[1], wantedOwner)
      || keyOf(split[2]) !== keyOf(wantedLabel)) {
      return result;
    }
    return {
      ...result,
      valid: true,
      combined: false,
      openingIndex: nonempty[0].index,
      headerIndex: nonempty[1].index,
      closingIndex: nonempty[nonempty.length - 1].index
    };
  }

  function canonicalOwnedEntryWrapper(value, owner, headerLabel) {
    const info = ownedEntryWrapperInfo(value, owner, headerLabel);
    if (!info.valid) {
      return { valid: false, changed: false, entry: info.source };
    }
    const bodyStart = info.combined ? info.openingIndex + 1 : info.headerIndex + 1;
    const body = info.rows.slice(bodyStart, info.closingIndex);
    const entry = [
      "{",
      line(owner, 120) + "'s " + line(headerLabel, 120) + ":",
      ...body,
      "}"
    ].join("\n");
    return {
      valid: true,
      changed: entry !== info.source,
      entry
    };
  }

  function physicalLogicalCardTitle(card) {
    const managed = managedTitleFromKey(card && card.keys);
    if (managed) return managed;
    const visible = visibleTitleOf(card);
    if (visible && !defaultScriptCardTitle(visible)) return visible;
    return managedTitleFromEntry(card);
  }

  function migrateOwnedCardTitles() {
    let migrated = 0;
    let failed = 0;
    cards.slice().forEach(card => {
      // Source-compiler cards use dormant keys until all six cards exist. The
      // ordinary ownership migration must not activate one of those cards early.
      if (importStagingCard(card)) return;
      const physical = physicalLogicalCardTitle(card);
      const intended = canonicalOwnedCardTitle(physical);
      const intendedParts = ownedCardTitleParts(intended);
      // Turning Point routers intentionally retain creator-authored trigger keys
      // and card types. Their exact possessive titles are required instead of
      // converting them into ordinary non-triggered CC cards.
      if (intendedParts && keyOf(intendedParts.label) === keyOf(settings.TURNING_POINTS_LABEL)) return;
      if (!intended || managedCardIdentityMatches(card, intended)) return;
      // Only migrate cards CC provably owns. A player is free to write their own
      // lore card called "Sarah's State"; rewriting its keys strips the triggers
      // it fires on and hands the card to CC to overwrite, with no notice beyond
      // a Debug counter that is off by default.
      if (!cardOwnedByContinuity(card)) return;
      const saved = saveCard(card, entryOf(card), intended);
      if (saved && managedCardIdentityMatches(saved, intended)) migrated += 1;
      else failed += 1;
    });
    if (migrated) {
      titleMigrationDiagnostics.push(
        "Migrated " + migrated + " character-owned card title"
          + (migrated === 1 ? "" : "s") + " to the possessive format in place."
      );
    }
    if (failed) {
      titleMigrationDiagnostics.push(
        failed + " character-owned card title" + (failed === 1 ? "" : "s")
          + " could not be migrated and remains readable through legacy-title compatibility."
      );
    }
  }

  function migrateOwnedEntryWrappers() {
    let migrated = 0;
    let failed = 0;
    cards.slice().forEach(card => {
      if (importStagingCard(card)) return;
      const parts = ownedCardTitleParts(physicalLogicalCardTitle(card));
      if (!parts || parts.page !== 1) return;
      const labelKey = keyOf(parts.label);
      const headerLabel = labelKey === keyOf(settings.OUTER_CHARACTER_LABEL)
        ? settings.OUTER_CHARACTER_LABEL
        : (labelKey === keyOf(settings.INNER_CHARACTER_LABEL)
          ? settings.INNER_CHARACTER_LABEL
          : (labelKey === keyOf(settings.STATE_LABEL) ? "current private State" : ""));
      if (!headerLabel) return;
      const normalized = canonicalOwnedEntryWrapper(entryOf(card), parts.owner, headerLabel);
      if (!normalized.valid || !normalized.changed) return;
      // saveCard rewrites keys and type as well as the entry, so the same
      // ownership rule as migrateOwnedCardTitles applies here.
      if (!cardOwnedByContinuity(card)) return;
      const saved = saveCard(card, normalized.entry, parts.title);
      if (saved && entryOf(saved) === normalized.entry) migrated += 1;
      else failed += 1;
    });
    if (migrated) {
      wrapperMigrationDiagnostics.push(
        "Migrated " + migrated + " Outer, Inner, or State entry wrapper"
          + (migrated === 1 ? "" : "s") + " to the split format in place."
      );
    }
    if (failed) {
      wrapperMigrationDiagnostics.push(
        failed + " legacy entry wrapper" + (failed === 1 ? "" : "s")
          + " could not be migrated and remains readable through compatibility parsing."
      );
    }
  }

  function ownedStructureMaintenanceSignature() {
    const rows = [];
    cards.forEach((card, index) => {
      if (!card) return;
      const physical = physicalLogicalCardTitle(card);
      const intended = canonicalOwnedCardTitle(physical);
      const parts = ownedCardTitleParts(intended);
      if (!intended || !parts) return;
      const label = keyOf(parts.label);
      let boundary = "";
      if ([settings.OUTER_CHARACTER_LABEL, settings.INNER_CHARACTER_LABEL, settings.STATE_LABEL]
        .some(value => keyOf(value) === label)) {
        const nonempty = entryOf(card).replace(/\r/g, "").split("\n")
          .map(row => row.trim()).filter(Boolean);
        boundary = hashString([
          nonempty[0] || "",
          nonempty[1] || "",
          nonempty[nonempty.length - 1] || ""
        ].join("\n"));
      }
      rows.push([
        index,
        intended,
        textOf(card.keys).trim(),
        visibleTitleOf(card),
        textOf(card.type).trim(),
        boundary
      ].join("\u241f"));
    });
    const joined = rows.join("\u241e");
    return rows.length + ":" + joined.length + ":" + hashString(joined)
      + ":" + hashString(rows.slice().reverse().join("\u241e"));
  }

  function managedStoreMaintenanceSignature() {
    const rows = currentCardCatalog().records.map(record => {
      const kind = storeKindForManagedTitle(record.title);
      if (!kind) return "";
      const entry = entryOf(record.card);
      return [
        record.index,
        kind,
        record.title,
        record.rawKey,
        textOf(record.card.type).trim(),
        entry.length,
        hashString(entry)
      ].join("\u241f");
    }).filter(Boolean);
    const joined = rows.join("\u241e");
    return rows.length + ":" + joined.length + ":" + hashString(joined)
      + ":" + hashString(rows.slice().reverse().join("\u241e"));
  }

  function duplicateCardEntrySignature(card) {
    return entryOf(card)
      .replace(/\r/g, "")
      .replace(/[ \t]+$/gm, "")
      .trim();
  }

  function strictBoundedWhole(value, fallback, minimum, maximum) {
    const source = textOf(value).trim();
    if (!/^\d+$/.test(source)) return { value: fallback, valid: false };
    const parsed = Number(source);
    if (!Number.isSafeInteger(parsed) || parsed < minimum || parsed > maximum) {
      return { value: fallback, valid: false };
    }
    return { value: parsed, valid: true };
  }

  function relationshipPaceSettings(source) {
    const presets = {
      slowburn: { name: "Slowburn", accumulated: 1, direct: 10, maxStages: 1 },
      balanced: { name: "Balanced", accumulated: 2, direct: 10, maxStages: 1 },
      fast: { name: "Fast", accumulated: 6, direct: 20, maxStages: 2 }
    };
    const rawPace = extractLine(source, "Relationship pace");
    const paceKey = keyOf(rawPace || settings.DEFAULT_RELATIONSHIP_PACE);
    const customAccumulated = strictBoundedWhole(
      extractLine(source, "Custom accumulated event value"),
      settings.DEFAULT_CUSTOM_RELATIONSHIP_ACCUMULATED,
      0,
      50
    );
    const customDirect = strictBoundedWhole(
      extractLine(source, "Custom direct event value"),
      settings.DEFAULT_CUSTOM_RELATIONSHIP_DIRECT,
      0,
      50
    );
    const customMaxStages = strictBoundedWhole(
      extractLine(source, "Custom maximum stages per operation"),
      settings.DEFAULT_CUSTOM_RELATIONSHIP_MAX_STAGES,
      1,
      6
    );
    const warnings = [];
    let pace;
    if (paceKey === "custom") {
      if (!customAccumulated.valid || !customDirect.valid || !customMaxStages.valid) {
        pace = { ...presets.balanced };
        warnings.push("Invalid Custom relationship values fell back to Balanced.");
      } else {
        pace = {
          name: "Custom",
          accumulated: customAccumulated.value,
          direct: customDirect.value,
          maxStages: customMaxStages.value
        };
      }
    } else if (presets[paceKey]) {
      pace = { ...presets[paceKey] };
    } else {
      pace = { ...presets.balanced };
      warnings.push("Relationship pace was missing or invalid and fell back to Balanced.");
    }
    return { pace, warning: warnings.join(" ") };
  }

  function turningPointModeSetting(source) {
    const supplied = keyOf(extractLine(source, "Turning Point mode") || settings.DEFAULT_TURNING_POINT_MODE);
    if (["growth only", "growthonly"].includes(supplied)) {
      return { mode: "growth-only", warning: "" };
    }
    if (["all directions", "all direction", "all"].includes(supplied)) {
      return { mode: "all-directions", warning: "" };
    }
    if (["disabled", "off", "none"].includes(supplied)) {
      return { mode: "disabled", warning: "" };
    }
    return {
      mode: "growth-only",
      warning: "Turning Point mode was missing or invalid and fell back to Growth-only."
    };
  }

  function settingsTemplate() {
    return [
      "Enabled: " + (settings.DEFAULT_ENABLED !== false),
      "Scene recognition: " + (settings.DEFAULT_SCENE_RECOGNITION !== false),
      "Scene-based NPC activation: " + (settings.DEFAULT_SCENE_CAST !== false),
      "Continuity budget: " + settings.DEFAULT_CONTINUITY_BUDGET,
      "State lifetime: " + settings.DEFAULT_STATE_LIFETIME,
      "Operation cooldown: " + settings.DEFAULT_OPERATION_COOLDOWN,
      "Maximum active NPCs: " + settings.DEFAULT_MAX_ACTIVE_NPCS,
      "Dynamic cast: " + (settings.DEFAULT_DYNAMIC_CAST !== false),
      "Side promotion interactions: " + settings.DEFAULT_SIDE_PROMOTION_INTERACTIONS,
      "Main inactivity limit: " + settings.DEFAULT_MAIN_INACTIVITY_LIMIT,
      "Relationship pace: " + settings.DEFAULT_RELATIONSHIP_PACE,
      "Custom accumulated event value: " + settings.DEFAULT_CUSTOM_RELATIONSHIP_ACCUMULATED,
      "Custom direct event value: " + settings.DEFAULT_CUSTOM_RELATIONSHIP_DIRECT,
      "Custom maximum stages per operation: " + settings.DEFAULT_CUSTOM_RELATIONSHIP_MAX_STAGES,
      "Turning Point mode: " + settings.DEFAULT_TURNING_POINT_MODE,
      "Relationship priority after shared moments: " + settings.DEFAULT_RELATIONSHIP_PRIORITY_MOMENTS,
      "Relationship starter after shared moments: " + settings.DEFAULT_RELATIONSHIP_STARTER_MOMENTS,
      "Timeline: " + (settings.DEFAULT_TIMELINE !== false),
      "Minutes per action: " + settings.DEFAULT_MINUTES_PER_ACTION,
      "Automatic events: " + (settings.DEFAULT_AUTO_EVENTS !== false),
      "Debug: " + (settings.DEFAULT_DEBUG === true)
    ].join("\n");
  }

  function hasSettingsField(source, label) {
    return new RegExp("^[ \\t]*" + escapeRegExp(label) + "[ \\t]*:", "im").test(textOf(source));
  }

  function ensureRelationshipSettings(card) {
    if (!card) return { card: null, warning: "" };
    const source = entryOf(card);
    const additions = [
      ["Scene recognition", settings.DEFAULT_SCENE_RECOGNITION !== false],
      ["Scene-based NPC activation", settings.DEFAULT_SCENE_CAST !== false],
      ["State lifetime", settings.DEFAULT_STATE_LIFETIME],
      ["Operation cooldown", settings.DEFAULT_OPERATION_COOLDOWN],
      ["Relationship pace", settings.DEFAULT_RELATIONSHIP_PACE],
      ["Custom accumulated event value", settings.DEFAULT_CUSTOM_RELATIONSHIP_ACCUMULATED],
      ["Custom direct event value", settings.DEFAULT_CUSTOM_RELATIONSHIP_DIRECT],
      ["Custom maximum stages per operation", settings.DEFAULT_CUSTOM_RELATIONSHIP_MAX_STAGES],
      ["Turning Point mode", settings.DEFAULT_TURNING_POINT_MODE],
      ["Relationship priority after shared moments", settings.DEFAULT_RELATIONSHIP_PRIORITY_MOMENTS],
      ["Relationship starter after shared moments", settings.DEFAULT_RELATIONSHIP_STARTER_MOMENTS],
      ["Timeline", settings.DEFAULT_TIMELINE !== false],
      ["Minutes per action", settings.DEFAULT_MINUTES_PER_ACTION],
      ["Automatic events", settings.DEFAULT_AUTO_EVENTS !== false]
    ].filter(([label]) => !hasSettingsField(source, label))
      .map(([label, value]) => label + ": " + value);
    if (!additions.length) return { card, warning: "" };
    const entry = [source.trimEnd(), additions.join("\n")].filter(Boolean).join("\n");
    const saved = saveCard(card, entry);
    return saved
      ? { card: saved, warning: "Added missing continuity controls to CC — Settings." }
      : { card, warning: "Missing continuity controls could not be added to CC — Settings." };
  }

  function readRuntime() {
    const title = settings.SETTINGS_TITLE;
    let card = findCard(title);
    if (!card) {
      card = addCard(title, settingsTemplate());
    }
    if (card) card = saveCard(card, entryOf(card), title) || card;
    const settingsUpgrade = ensureRelationshipSettings(card);
    card = settingsUpgrade.card || card;
    const source = card ? entryOf(card) : "";
    const rawContinuityBudget = extractLine(source, "Continuity budget");
    const defaultContinuityBudget = settings.DEFAULT_CONTINUITY_BUDGET;
    const minimumContinuityBudget = settings.MIN_CONTINUITY_BUDGET;
    const parsedContinuityBudget = positiveWhole(rawContinuityBudget, defaultContinuityBudget);
    const continuityBudget = Math.max(minimumContinuityBudget, parsedContinuityBudget);
    const budgetWarning = rawContinuityBudget && parsedContinuityBudget !== Number(rawContinuityBudget)
      ? "Continuity budget was invalid and defaulted to " + defaultContinuityBudget + "."
      : (rawContinuityBudget && parsedContinuityBudget < minimumContinuityBudget
        ? "Continuity budget was raised to the required " + minimumContinuityBudget + "-token minimum."
      : (!rawContinuityBudget && card
        ? "Continuity budget was missing and defaulted to " + defaultContinuityBudget + "."
        : ""));
    const rawOperationCooldown = extractLine(source, "Operation cooldown").trim();
    const parsedOperationCooldown = Number(rawOperationCooldown);
    const validOperationCooldown = /^\d+$/.test(rawOperationCooldown)
      && Number.isSafeInteger(parsedOperationCooldown) && parsedOperationCooldown <= 999;
    const operationCooldown = validOperationCooldown
      ? parsedOperationCooldown : settings.DEFAULT_OPERATION_COOLDOWN;
    const cooldownWarning = validOperationCooldown ? ""
      : "Operation cooldown must be a whole number from 0 to 999; using "
        + settings.DEFAULT_OPERATION_COOLDOWN + " turns.";
    const relationshipPace = relationshipPaceSettings(source);
    const turningPointMode = turningPointModeSetting(source);
    return {
      enabled: boolValue(extractLine(source, "Enabled"), settings.DEFAULT_ENABLED !== false),
      sceneRecognition: boolValue(extractLine(source, "Scene recognition"), settings.DEFAULT_SCENE_RECOGNITION !== false),
      sceneCast: boolValue(extractLine(source, "Scene recognition"), settings.DEFAULT_SCENE_RECOGNITION !== false)
        && boolValue(extractLine(source, "Scene-based NPC activation"), settings.DEFAULT_SCENE_CAST !== false),
      continuityBudget,
      operationCooldown,
      stateLifetime: numberValue(
        extractLine(source, "State lifetime"),
        settings.DEFAULT_STATE_LIFETIME,
        1,
        12
      ),
      maxActive: numberValue(
        extractLine(source, "Maximum active NPCs"),
        settings.DEFAULT_MAX_ACTIVE_NPCS,
        1,
        settings.MAX_ACTIVE_NPCS
      ),
      dynamicCast: boolValue(
        extractLine(source, "Dynamic cast"),
        settings.DEFAULT_DYNAMIC_CAST !== false
      ),
      sidePromotionInteractions: numberValue(
        extractLine(source, "Side promotion interactions"),
        settings.DEFAULT_SIDE_PROMOTION_INTERACTIONS,
        1,
        999
      ),
      mainInactivityLimit: numberValue(
        extractLine(source, "Main inactivity limit"),
        settings.DEFAULT_MAIN_INACTIVITY_LIMIT,
        1,
        999
      ),
      debug: boolValue(extractLine(source, "Debug"), settings.DEFAULT_DEBUG === true),
      relationshipPriorityMoments: numberValue(extractLine(source, "Relationship priority after shared moments"),
        settings.DEFAULT_RELATIONSHIP_PRIORITY_MOMENTS, 0, 999),
      relationshipStarterMoments: numberValue(extractLine(source, "Relationship starter after shared moments"),
        settings.DEFAULT_RELATIONSHIP_STARTER_MOMENTS, 0, 999),
      timeline: boolValue(extractLine(source, "Timeline"), settings.DEFAULT_TIMELINE !== false),
      minutesPerAction: numberValue(extractLine(source, "Minutes per action"), settings.DEFAULT_MINUTES_PER_ACTION, 0, 1440),
      autoEvents: boolValue(extractLine(source, "Automatic events"), settings.DEFAULT_AUTO_EVENTS !== false),
      relationshipPace: relationshipPace.pace,
      turningPointMode: turningPointMode.mode,
      warning: [card ? "" : "The Settings card could not be created.", settingsUpgrade.warning, budgetWarning, cooldownWarning, relationshipPace.warning, turningPointMode.warning]
        .filter(Boolean).join(" ")
    };
  }

  const runtime = readRuntime();
  if (!runtime.enabled) {
    return finish(originalText);
  }

  function ensureSettingScene() {
    const result = { warnings: [] };
    if (!runtime.sceneRecognition) return result;
    const title = "Setting's Scene";
    const legacyNotes = "CC scene recognition. Setting takes its own assessment turn without occupying an NPC roster slot. "
      + "Scene recognition in CC — Settings controls assessment and pacing. Occasion records the current activity or interaction. "
      + "Phase: Unfolding, Settling, or Ready for transition; blank means unspecified. Unresolved beat records one immediate pending response, choice, action, or consequence. "
      + "Preserve ongoing scenes and quiet moments; no fixed turn quota. Ready for transition permits an ending without forcing one. "
      + "Follow the narrated focus, including enacted cutaways and fully narrated flashbacks. Plans and recalled events alone do not change scenes. "
      + "Newer narration and Player actions override the last assessment. No participant tracking, Map, Timeline, or countdown automation is included.";
    const notes = "CC scene recognition. Setting assesses the narrated scene without occupying an NPC roster slot. "
      + "Scene recognition controls pacing; Scene-based NPC activation controls selection from the registered roster. "
      + "Occasion is the current interaction. Phase is Unfolding, Settling, or Ready for transition. Unresolved beat is one immediate pending response, action, choice, or consequence. "
      + "Participants lists canonical NPC names as a JSON array, or NONE when no registered NPC participates, or UNKNOWN pending assessment. "
      + "Quiet participants stay present until evidence establishes departure or a new narrated scene. Mentions, plans, memories, and quoted speech alone do not establish participation. Live remote conversations may participate. "
      + "All participants stay recorded even when the context selects only five. Inactive characters retain their cards and identities. "
      + "Newer enacted narration and Player actions override the last assessment. No fixed turn quota, forced ending, or Map automation; "
      + "when Timeline is on in CC — Settings, time and countdowns live in Setting's Timeline and Setting's Event Countdowns.";
    const v3020Notes = notes.slice(0, notes.indexOf("No fixed turn quota")) + "No fixed turn quota, forced ending, Map, Timeline, or countdown automation.";
    const matching = uniqueCards(managedCardMatches(title).concat(
      cards.filter(card => settingTitleFromEntry(card) === title)
    ));
    if (matching.length) {
      if (matching.length > 1) {
        result.warnings.push("Multiple Setting's Scene cards were found; all were preserved for creator review.");
        return result;
      }
      let card = matching[0];
      const source = entryOf(card);
      const rows = source.replace(/\r/g, "").split("\n");
      if (runtime.sceneCast && !rows.some(row => /^[ \t]*Participants[ \t]*:/i.test(row))) {
        const close = rows.map(row => row.trim()).lastIndexOf("}");
        const safe = settingTitleFromEntry(card) === title && source.trim().endsWith("}") && close >= 0
          && ["Occasion", "Phase", "Unresolved beat"].every(field =>
            rows.filter(row => new RegExp("^[ \\t]*" + escapeRegExp(field) + "[ \\t]*:", "i").test(row)).length === 1);
        if (safe) {
          rows.splice(close, 0, "Participants: UNKNOWN");
          const saved = saveCard(card, rows.join(source.includes("\r\n") ? "\r\n" : "\n"), title);
          if (saved) card = saved;
          else result.warnings.push("The Scene participant field could not be added; the original Scene was preserved.");
        } else result.warnings.push("Setting's Scene needs a complete unambiguous wrapper before participant tracking can be added.");
      }
      if (notesOf(card) === legacyNotes || notesOf(card) === v3020Notes) restoreCardNotes(card, notes);
      return result;
    }
    const entry = ["{", title + ":", "Occasion:", "Phase:", "Unresolved beat:",
      ...(runtime.sceneCast ? ["Participants: UNKNOWN"] : []), "}"].join("\n");
    if (!addCard(title, entry, notes)) result.warnings.push("Setting's Scene could not be created; creation will be retried on a later enabled hook.");
    return result;
  }

  const sceneSetup = ensureSettingScene();

  function normalizeSceneRecognition(value) {
    const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
    const served = Number(source.lastServedGeneration);
    return {
      lastServedGeneration: Number.isFinite(served) ? Math.max(-1, Math.floor(served)) : -1,
      lastAssessedEvidenceNumber: Math.max(0, Math.floor(Number(source.lastAssessedEvidenceNumber) || 0)),
      lastChange: settings.SCENE_CHANGES.includes(source.lastChange) ? source.lastChange : "",
      lastResult: line(source.lastResult, 300),
      needsReassessment: source.needsReassessment === true,
      lastCommittedEntry: textOf(source.lastCommittedEntry),
      participantRosterSignature: runtime.sceneCast ? textOf(source.participantRosterSignature) : ""
    };
  }


  function currentSceneCard() {
    const title = "Setting's Scene";
    const matches = uniqueCards(managedCardMatches(title).concat(
      cards.filter(card => settingTitleFromEntry(card) === title)
    ));
    if (matches.length !== 1) return { ok: false, error: "Scene recognition needs one unambiguous Setting's Scene card." };
    const card = matches[0];
    const entry = entryOf(card);
    const rows = entry.replace(/\r/g, "").split("\n");
    if (settingTitleFromEntry(card) !== title || !entry.trim().endsWith("}")) {
      return { ok: false, error: "Setting's Scene needs its complete Scene wrapper; creator content was preserved." };
    }
    const values = {};
    const indexes = {};
    for (const field of ["Occasion", "Phase", "Unresolved beat"]) {
      const pattern = new RegExp("^[ \\t]*" + escapeRegExp(field) + "[ \\t]*:[ \\t]*(.*)$", "i");
      const matching = rows.map((row, index) => ({ match: row.match(pattern), index })).filter(item => item.match);
      if (matching.length !== 1) return { ok: false, error: "Setting's Scene needs exactly one " + field + " field; creator content was preserved." };
      values[field] = matching[0].match[1].trim();
      indexes[field] = matching[0].index;
    }
    const participantRows = rows.map((row, index) => ({ match: row.match(/^[ \t]*Participants[ \t]*:[ \t]*(.*)$/i), index }))
      .filter(item => item.match);
    if (runtime.sceneCast && participantRows.length !== 1) {
      return { ok: false, error: "Setting's Scene needs exactly one Participants field; creator content was preserved." };
    }
    if (participantRows.length === 1) {
      values.Participants = participantRows[0].match[1].trim();
      indexes.Participants = participantRows[0].index;
      const participants = parseSceneParticipants(values.Participants);
      if (runtime.sceneCast && !participants.ok) return { ok: false, error: participants.error };
    }
    if (values.Phase && !settings.SCENE_PHASES.includes(values.Phase)) {
      return { ok: false, error: "Setting's Scene has an unrecognized Phase; use Unfolding, Settling, or Ready for transition." };
    }
    return { ok: true, card, entry, rows, values, indexes, newline: entry.includes("\r\n") ? "\r\n" : "\n" };
  }


  function captureSceneCard() {
    const scene = currentSceneCard();
    return scene.ok ? { entry: scene.entry } : null;
  }


  function restoreSceneCard(snapshot, committedEntry) {
    if (!snapshot || typeof snapshot.entry !== "string") return true;
    const scene = currentSceneCard();
    if (!scene.ok) return false;
    if (scene.entry === snapshot.entry) return true;
    // Undo this generation's write only. Later creator edits remain authoritative.
    if (!committedEntry || scene.entry !== committedEntry) return true;
    const saved = saveCard(scene.card, snapshot.entry, "Setting's Scene");
    return !!saved && entryOf(saved) === snapshot.entry;
  }


  function scenePacingContext() {
    if (!runtime.sceneRecognition || CC.sceneRecognition.needsReassessment) return "";
    const scene = currentSceneCard();
    if (!scene.ok || !Object.values(scene.values).some(Boolean)) return "";
    const phase = scene.values.Phase;
    const guidance = {
      Unfolding: "Develop the current interaction and leave meaningful pending responses or choices room.",
      Settling: "Give the main event's immediate reactions and consequences room before moving on.",
      "Ready for transition": "Allow a natural ending or transition when appropriate; readiness does not require ending the scene."
    }[phase] || "Follow the current interaction without assuming its phase.";
    return [
      "CC SCENE PACING — last assessed narrated scene; newer narration and Player actions take precedence:",
      "Occasion: " + shortenProfileValue(scene.values.Occasion || "Unspecified", settings.MAX_SCENE_OCCASION_CHARS),
      "Phase: " + (phase || "Unspecified"),
      "Unresolved beat: " + shortenProfileValue(scene.values["Unresolved beat"] || "None recorded", settings.MAX_SCENE_BEAT_CHARS),
      runtime.sceneCast ? "Registered scene participants: " + (() => {
        const present = sceneParticipants();
        return present.known ? present.names.join(", ") || "None" : "Awaiting assessment";
      })() + ". References to absent people do not make them present." : "",
      guidance,
      "Advance meaningful developments rather than repeating the same hesitation or description. Use no turn quota. Interruptions, cutaways, and Player-led changes remain possible; never invent the Player's response or keep every scene open for a long-term plot problem."
    ].filter(Boolean).join("\n");
  }


  function parseSceneParticipants(value) {
    const text = textOf(value).trim();
    if (!text || /^UNKNOWN$/i.test(text)) return { ok: true, known: false, names: [] };
    if (/^NONE$/i.test(text)) return { ok: true, known: true, names: [] };
    let names;
    try { names = JSON.parse(text); } catch { names = null; }
    if (!Array.isArray(names) || names.length > settings.MAX_ROSTER_NPCS
      || names.some(name => typeof name !== "string" || !name.trim() || name !== name.trim()
        || name.length > 120 || /[\r\n]/.test(name))
      || new Set(names.map(nameKeyOf)).size !== names.length) {
      return { ok: false, known: false, names: [],
        error: "Scene Participants must be UNKNOWN, NONE, or a JSON array of distinct canonical NPC names." };
    }
    return { ok: true, known: true, names };
  }

  function sceneRosterCatalog() {
    return activeNpcRoster.slots.filter(slot => slot && slot.valid && slot.name).map(slot => {
      const character = characterForActiveRosterName(slot.name);
      const aliases = character ? uniqueNameForms(character.aliases || [], 120)
        .filter(alias => !sameNameForm(alias, slot.name)).slice(0, 3) : [];
      return { code: slot.code, key: nameKeyOf(slot.name), name: slot.name, aliases };
    });
  }

  function sceneRosterSignature(roster = sceneRosterCatalog()) {
    return hashString(JSON.stringify(roster.map(item => [item.code, item.key, item.name])));
  }

  function sceneParticipants() {
    const scene = currentSceneCard();
    if (!scene.ok) return { known: false, names: [], characters: [], error: scene.error };
    const parsed = parseSceneParticipants(scene.values.Participants);
    if (!parsed.ok || CC.sceneRecognition.needsReassessment
      || CC.sceneRecognition.participantRosterSignature !== sceneRosterSignature()) {
      return { known: false, names: parsed.names || [], characters: [], error: parsed.error || "Scene needs reassessment." };
    }
    const present = new Set(parsed.names.map(nameKeyOf));
    return { known: parsed.known, names: parsed.names,
      characters: parsed.known ? activeNpcRosterCharacters().filter(character => present.has(nameKeyOf(character.name))) : [],
      error: "" };
  }

  function sceneCharacterEligible(character) {
    return !!character && (!runtime.sceneCast || sceneParticipants().characters.some(item => item.key === character.key));
  }

  function sceneCastRequest(scene) {
    if (!runtime.sceneCast) return null;
    const roster = sceneRosterCatalog();
    const parsed = parseSceneParticipants(scene.values.Participants);
    const signature = sceneRosterSignature(roster);
    const baselineCodes = roster.filter(item => parsed.names.some(name => sameNameForm(name, item.name)))
      .map(item => item.code);
    return { roster, signature, baselineCodes,
      baselineKnown: parsed.ok && parsed.known && !CC.sceneRecognition.needsReassessment,
      requiresFresh: CC.sceneRecognition.needsReassessment
        || !parsed.ok || !parsed.known
        || CC.sceneRecognition.participantRosterSignature !== signature
        || parsed.names.some(name => !roster.some(item => sameNameForm(item.name, name))) };
  }

  function sceneCastTaskLines(request) {
    const cast = request.cast;
    if (!cast) return [];
    return [
      "REGISTERED NPCS (identity catalog only; a name here does not mean present): "
        + (cast.roster.map(item => item.code + "=" + item.name
          + (cast.showAliases !== false && item.aliases.length ? " [aliases: " + item.aliases.join(", ") + "]" : "")).join("; ") || "None"),
      "Previously assessed participants: " + (cast.baselineKnown ? cast.baselineCodes.join(",") || "NONE" : "UNKNOWN") + ".",
      "Participants: list ALL registered NPCs physically present or directly participating in a live remote conversation at the END of completed evidence. Use comma-separated N-codes, NONE for no registered participant, or UNKNOWN if the current cast cannot be established. Never list Player or invent an NPC/code. The five-NPC context limit does not limit this list.",
      "Keep quiet participants in an ongoing scene until evidence establishes departure. A mention, plan, wish, memory, quotation, or discussion ABOUT someone does not place them in the scene. Invitations do not establish arrival. Follow enacted arrivals/departures, cutaways and fully narrated flashbacks; reconstruct the cast when narrated focus changes. Only the narrated scene grants presence, not a shared location alone.",
      cast.requiresFresh ? "Participants requires a fresh list, NONE, or UNKNOWN; KEEP is unavailable."
        : "For Continue, KEEP retains the previous participant list. For Transition, Timeskip, Cutaway, Flashback or Return, explicitly reassess the entire list; do not carry everyone across automatically."
    ];
  }

  function parseSceneCastResponse(value, request, change) {
    if (!request.cast) return { ok: true, value: null };
    if (!runtime.sceneCast) return { ok: false, error: "Scene-based NPC activation was disabled after the request." };
    const cast = request.cast;
    const text = textOf(value).trim();
    if (text === "KEEP") {
      if (cast.requiresFresh || !cast.baselineKnown || change !== "Continue") {
        return { ok: false, error: "Scene Participants needs an explicit reassessment; KEEP was not authorized." };
      }
      const names = cast.roster.filter(item => cast.baselineCodes.includes(item.code)).map(item => item.name);
      return { ok: true, value: names.length ? JSON.stringify(names) : "NONE" };
    }
    if (text === "NONE" || text === "UNKNOWN") return { ok: true, value: text };
    const codes = text.split(",").map(item => item.trim());
    if (!codes.length || codes.length > settings.MAX_ROSTER_NPCS || new Set(codes).size !== codes.length
      || codes.some(code => !canonicalNpcSlotCode(code) || code !== canonicalNpcSlotCode(code)
        || !cast.roster.some(item => item.code === code))) {
      return { ok: false, error: "Scene Participants contained an invalid, duplicate, or unregistered NPC code." };
    }
    return { ok: true, value: JSON.stringify(cast.roster.filter(item => codes.includes(item.code)).map(item => item.name)) };
  }

  function sceneCastReviewReason(plan, base) {
    if (!runtime.sceneCast || !plan || plan.opening || plan.retry || !plan.opportunity) return "";
    const participants = sceneParticipants();
    if (!participants.known) return "Scene participants need an initial or fresh assessment.";
    if (CC.sceneRecognition.participantRosterSignature !== sceneRosterSignature()) return "The registered roster changed.";
    const recent = canonicalOutput(recentStoryFromContext(base));
    const fresh = CC.evidence.filter(item => ["input", "story", "opening"].includes(item.source)
      && item.number > CC.sceneRecognition.lastAssessedEvidenceNumber
      && (item.id === plan.inputEvidenceId || anchorInText(item.anchor, recent)))
      .map(item => sceneFullEvidence(item, recent, plan.inputEvidenceId) || item.text).join("\n");
    if (!fresh) return "";
    const present = new Set(participants.characters.map(character => character.key));
    if (activeNpcRosterCharacters().some(character => !present.has(character.key)
      && characterMentioned(fresh, character, false, Array.from(present)))) {
      return "A registered NPC outside the confirmed cast was mentioned; assess participation before activating them.";
    }
    // These broad cues only request a semantic review. They never assign presence.
    if (/\b(?:arriv\w*|depart\w*|enter\w*|exit\w*|leav(?:e|es|ing)|left|join\w*|return\w*|walk(?:s|ed|ing)? away|go(?:es|ing)? (?:home|outside|back)|went (?:home|outside|back)|cutaway|flashback|meanwhile|elsewhere|hangs? up|hung up|disconnect\w*)\b/i.test(fresh)
      || sceneTimeJump(fresh)) return "Possible arrival, departure, or narrated scene change needs assessment.";
    return "";
  }

  function sceneTurnDue(plan, active, focus, queuedImport) {
    if (!runtime.sceneRecognition || !plan || !plan.opportunity || plan.opening || CC.recoveryPending) return false;
    if (plan.settingTurn === true) return true;
    if (runtime.sceneCast && plan.sceneCastReviewReason && !plan.retry && !plan.operationSelectionFrozen) return true;
    if (queuedImport) return false;
    if (plan.retry || plan.pendingOperationRetry || plan.operationSelectionFrozen) return false;
    const scene = currentSceneCard();
    if (!scene.ok) {
      CC.sceneRecognition.lastResult = scene.error;
      return false;
    }
    if (!focus || !active.length) return true;
    const served = Number(CC.focusLastServed[focus.key]);
    const npcLastServed = Number.isFinite(served) ? served : -1;
    // Equal ages favor the NPC; oldest-served selection prevents Setting starvation.
    return CC.sceneRecognition.lastServedGeneration < npcLastServed;
  }


  function sceneFullEvidence(item, recent, currentInputId) {
    // The ordinary ledger may retain only a head/tail excerpt. Recover the
    // whole original passage by length AND hash, never by matching its ends
    // alone: an edited or discarded middle must not acquire evidence authority.
    const anchor = item && item.anchor;
    if (anchor && anchor.start && anchor.end && Number.isSafeInteger(anchor.chars)
      && anchor.chars > 0 && anchor.chars <= recent.length) {
      let index = recent.indexOf(anchor.start);
      while (index >= 0) {
        const passage = recent.slice(index, index + anchor.chars);
        if (passage.length === anchor.chars && passage.endsWith(anchor.end)
          && hashString(passage) === anchor.hash) return passage;
        index = recent.indexOf(anchor.start, index + 1);
      }
    }
    // The current input can live outside Recent Story. A complete input is
    // safe to repeat inline; a stored excerpt is never treated as a full turn.
    if (item && item.id === currentInputId && item.source === "input" && !item.clipped) {
      const passage = canonicalOutput(item.text);
      if (passage && (!anchor || (passage.length === anchor.chars
        && hashString(passage) === anchor.hash))) return passage;
    }
    return "";
  }


  function sceneReferenceMatches(reference, passage, recent) {
    if (!reference || !reference.start || !reference.end || !passage) return false;
    const start = recent.indexOf(reference.start);
    const end = recent.indexOf(reference.end);
    return start >= 0 && end >= start
      && recent.lastIndexOf(reference.start) === start
      && recent.lastIndexOf(reference.end) === end
      && recent.slice(start, end + reference.end.length) === passage;
  }


  function sceneEvidenceReference(passage, recent) {
    if (passage.length <= settings.MAX_SCENE_INLINE_EVIDENCE_CHARS) return null;
    // These are locators, not summaries. Use them only when both boundaries
    // identify one exact complete passage in the context actually delivered.
    for (const length of [64, 120, 160]) {
      if (length * 2 >= passage.length) break;
      const reference = { start: passage.slice(0, length), end: passage.slice(-length) };
      if (sceneReferenceMatches(reference, passage, recent)) return reference;
    }
    return null;
  }


  function sceneEvidenceRow(item) {
    return item.reference
      ? item.id + " [" + item.source + "; Recent Story]: START="
        + JSON.stringify(item.reference.start) + " END=" + JSON.stringify(item.reference.end)
      : item.id + " [" + item.source + "]: " + item.text;
  }


  function sceneRequestEvidenceAvailable(request, base) {
    // recentStoryFromContext can fall back to platform history, which is not
    // necessarily visible to the model. Only reference the actual context.
    const recent = textOf(base).includes("Recent Story:")
      ? canonicalOutput(recentStoryFromContext(base)) : "";
    return request.evidence.every(item => !item.reference
      || sceneReferenceMatches(item.reference, item.text, recent));
  }


  function makeSceneRequest(plan, base = originalText) {
    if (plan.sceneRequest) return plan.sceneRequest;
    const scene = currentSceneCard();
    if (!scene.ok) return null;
    const recent = canonicalOutput(recentStoryFromContext(base));
    const visibleRecent = textOf(base).includes("Recent Story:") ? recent : "";
    const evidence = CC.evidence.filter(item => /^E\d+$/.test(item.id)
      && ["input", "story", "opening"].includes(item.source)
      && (item.id === plan.inputEvidenceId || anchorInText(item.anchor, recent)))
      .slice().sort((a, b) => b.number - a.number)
      .slice(0, settings.MAX_SCENE_EVIDENCE_ITEMS).reverse()
      .map(item => {
        const passage = sceneFullEvidence(item, recent, plan.inputEvidenceId)
          || (item.id === plan.inputEvidenceId
            ? sceneFullEvidence(item, canonicalOutput(base), plan.inputEvidenceId) : "");
        if (!passage) {
          CC.last.evidenceDiagnostics = (CC.last.evidenceDiagnostics || []).concat(
            item.id + " omitted from Scene assessment: its complete original passage is unavailable."
          ).slice(-20);
          return null;
        }
        return { id: item.id, number: item.number, source: item.source,
          hash: hashString(item.text), text: passage, complete: true,
          reference: sceneEvidenceReference(passage, visibleRecent) };
      }).filter(Boolean);
    if (!evidence.length) return null;
    const cast = sceneCastRequest(scene);
    const signature = [CC.inputCount, plan.actionCount, CC.visibleGenerationCount, scene.entry, JSON.stringify(cast),
      ...evidence.map(item => item.id + ":" + item.hash
        + ":" + hashString(item.text) + ":" + JSON.stringify(item.reference))].join("\u241f");
    return {
      id: "Q" + hashString(signature), baselineEntry: scene.entry,
      baseline: clone(scene.values), evidence, deliveryFrozen: false,
      time: timelineSceneRequest(evidence),
      cast, castEnabled: runtime.sceneCast,
      requiresFresh: CC.sceneRecognition.needsReassessment === true
    };
  }


  function sceneAssessmentTask(request) {
    return [
      "<SYSTEM>",
      "CC SCENE ASSESSMENT — Setting is the sole continuity subject this turn.",
      "Assess the active narrated scene at the END of completed evidence, before writing the continuation. Follow enacted cutaways and fully narrated flashbacks, not just the Player's whereabouts. Do not use the story you are about to write as evidence.",
      request.time
        ? "Update Elapsed, Time of day, Occasion, Phase, Unresolved beat" + (request.cast ? ", and Participants" : "") + " only. Do not emit NPC records."
        : "Update Occasion, Phase, Unresolved beat" + (request.cast ? ", and Participants" : "") + " only. Do not advance time/countdowns or emit NPC records.",
      "Previous Occasion: " + shortenProfileValue(request.baseline.Occasion || "Unspecified", 180),
      "Previous Phase: " + (request.baseline.Phase || "Unspecified"),
      "Previous Unresolved beat: " + shortenProfileValue(request.baseline["Unresolved beat"] || "None recorded", 200),
      request.requiresFresh ? "Scene history needs reassessment: reassess all three Scene fields; KEEP is unavailable for them." : "",
      "Completed evidence, oldest to newest; latest enacted scene takes precedence:",
      request.evidence.some(item => item.reference)
        ? "Recent Story references supply the ENTIRE passage from START through END, inclusive. Read its middle too. These anchors only locate the passage; assess its whole contents. Whitespace is normalized." : "",
      ...request.evidence.map(sceneEvidenceRow),
      "Change: Continue, Transition, Timeskip, Cutaway, Flashback, or Return, relative to the previous assessed scene. Mentioning a place, recalling it in dialogue, or planning travel does not enact a change. A fully narrated flashback changes focus without advancing present-day time.",
      ...timelineSceneTaskLines(request),
      "Occasion: current activity/interaction, at most " + settings.MAX_SCENE_OCCASION_CHARS + " characters. Preserve it unless the narrative changes it.",
      "Phase: Unfolding while meaningful interaction develops; Settling while immediate reactions/consequences remain; Ready for transition when the occasion has run its course. Readiness permits but never forces an ending. No turn quota; phases may repeat, reverse, or be skipped. Repeated description alone is not progress.",
      "Unresolved beat: one immediate pending response, action, choice, or consequence, at most " + settings.MAX_SCENE_BEAT_CHARS + " characters; NONE clears it. Long-term plot problems do not keep every scene open. KEEP preserves any prior Scene field; never invent missing facts or the Player's response.",
      ...sceneCastTaskLines(request),
      "Complete exactly this record as the FIRST nonblank line, then write complete story prose:",
      "(CCSCENE|" + request.id + "|EvidenceIDs|Change" + (request.time ? "|Elapsed|Time of day" : "") + "|Occasion|Phase|Unresolved beat" + (request.cast ? "|Participants" : "") + ")",
      "Cite supplied EvidenceIDs in listed order, comma-separated, including the newest supplied evidence. Replace every placeholder. Fields must be single lines without |, parentheses, brackets, braces, or angle brackets. Output one CCSCENE only; no CCO, CCP, or CCI. The record is hidden from the story.",
      "</SYSTEM>"
    ].filter(Boolean).join("\n");
  }


  function wholePortrayalProfiles(active, focus, tier = "full") {
    const ordered = focus ? [focus].concat(active.filter(item => item.key !== focus.key)) : active.slice();
    return ordered.filter(character => !character.onboardingPending).map(character => ({ character,
      text: (tier === "compact"
        ? [compactOperationOuterAnchor(character), compactOperationInnerAnchor(character)]
        : tier === "emergency"
          ? [emergencyPortrayalOuterAnchor(character), emergencyPortrayalInnerAnchor(character)]
          : [outerAnchor(character), innerAnchor(character)]).filter(Boolean).join("\n") }));
  }


  function extendWholePortrayal(chosen, profiles, fit, plan) {
    let fitted = fit(chosen);
    if (!fitted.ok) return fitted;
    const recent = recentStoryFromContext(originalText);
    const currentInput = plan.kind === "input" || plan.retry ? CC.lastInput : "";
    const active = profiles.map(item => item.character);
    const focus = chosen.length ? chosen[0].character : null;
    const add = item => {
      if (!item || !item.text) return true;
      const expanded = fit(chosen.concat(item));
      if (!expanded.ok) return false;
      chosen.push(item);
      fitted = expanded;
      return true;
    };
    const addTurningPoints = owner => {
      const data = turningPointsForOwner(owner.key);
      (data && data.contextRecords || []).forEach(record => {
        const resolution = turningPointStageCardResolution(record, owner, record.progress.stageRecord);
        if (!resolution.ok) return;
        const marker = turningPointContextMarker(owner, record, resolution);
        if (!marker || !add({ text: marker })) return;
        add({ text: turningPointContextStageBlock(owner, record, resolution) });
      });
    };
    if (focus) {
      relevantRelationshipRecords(focus, active, currentInput, recent).slice(0, 2).forEach(selection => {
        add({ text: renderRelevantRelationshipsBlock(focus, [selection]) });
      });
      addTurningPoints(focus);
    }
    profiles.slice(1).forEach(profile => { if (add(profile)) addTurningPoints(profile.character); });
    const modelActive = chosen.filter(item => item.character).map(item => item.character);
    const addNames = identity => {
      if (!identity) return;
      relevantNameRecords(identity, currentInput, recent, modelActive).slice(0, 3).forEach(selection => {
        add({ text: renderRelevantNamesBlock(identity, [selection]) });
      });
    };
    addNames(nameIdentityForKey("player"));
    modelActive.forEach(owner => {
      addNames(nameIdentityForKey("npc:" + owner.key));
      add({ text: temporaryStateLine(owner) });
      if (owner !== focus) {
        const relationship = relevantRelationshipRecords(owner, modelActive, currentInput, recent)[0];
        if (relationship) add({ text: renderRelevantRelationshipsBlock(owner, [relationship]) });
      }
      const experience = relevantExperienceRecords(owner, currentInput, recent, [])[0];
      if (experience) add({ text: renderRelevantExperienceBlock(owner, experience) });
      const activeViews = relevantViewRecords(owner, modelActive, currentInput, recent, [], false);
      const buriedViews = relevantViewRecords(owner, modelActive, currentInput, recent, [], true);
      relevantRecoveredBlocks(owner, activeViews, buriedViews).forEach(block => add({ text: block.text }));
      activeViews.filter(item => !recoveringMarker(owner.key, item.record.targetKey)).forEach(selection => {
        add({ text: renderRelevantViewsBlock(owner, [selection]) });
      });
    });
    return fitted;
  }


  function buildSceneContext(base, active, focus, plan, commitContextSuffix) {
    plan.settingTurn = true;
    plan.sceneTaskDelivered = false;
    plan.task = "scene";
    plan.taskDelivered = false;
    plan.profileTaskDelivered = false;
    plan.developmentRequest = null;
    plan.ownerKey = "";
    plan.focusKey = "";
    plan.selectedOperationKind = "";
    plan.selectedCandidate = null;
    plan.targets = [];
    plan.operationTaskText = "";
    plan.operationSelectionFrozen = false;
    plan.activeKeys = active.map(character => character.key);
    plan.modelActiveKeys = [];
    CC.activeKeys = plan.activeKeys.slice();
    CC.modelActiveKeys = [];
    CC.focusKey = "";
    const defer = () => {
      plan.task = "none";
      plan.sceneTaskDelivered = false;
      if (active.length && focus && !plan.retry && !(runtime.sceneCast && plan.sceneCastReviewReason)) {
        // A Scene packet that cannot fit must not indefinitely prevent fitting
        // NPC work. No Scene authority or half-delivered request survives fallback.
        plan.settingTurn = false;
        delete plan.sceneRequest;
        plan.evidenceIds = [];
        return null;
      }
      recordGenuineContextPlan(plan, CC.sceneRecognition.lastResult);
      return appendScenePacingContext(base, commitContextSuffix);
    };
    const request = makeSceneRequest(plan, base);
    if (!request) {
      CC.sceneRecognition.lastResult = "Scene assessment deferred: no safe Scene card or complete evidence passage.";
      CC.last.context = CC.sceneRecognition.lastResult;
      return defer();
    }
    if (!sceneRequestEvidenceAvailable(request, base)) {
      CC.sceneRecognition.lastResult = "Scene assessment deferred: a frozen full-passage reference is missing or changed in the current context.";
      CC.last.context = CC.sceneRecognition.lastResult;
      return defer();
    }
    plan.sceneRequest = clone(request);
    plan.evidenceIds = request.evidence.map(item => item.id);
    let task = sceneAssessmentTask(request);
    const suffixInstruction = "Setting is this turn's only continuity subject. Complete the requested CCSCENE record as the first nonblank response line, then write complete story prose. Do not output CCO, CCP, or CCI.";
    const suffix = ownedContextSuffixBlock(suffixInstruction);
    const maxChars = Number(typeof info !== "undefined" && info ? info.maxChars : 0) || 0;
    const capacity = continuityCapacity(base, maxChars);
    const rules = scenePortrayalRules();
    let profiles = wholePortrayalProfiles(active, focus);
    let portrayalTier = "full";
    let chosen = [];
    const fit = parts => {
      const prefix = renderPortrayalComponents([{ text: rules }].concat(parts.map(item => ({ text: item.text }))));
      const tokens = estimateTokens([prefix, task, suffix].join("\n\n"));
      if (tokens > capacity.effectiveBudget || tokens > runtime.continuityBudget) return { ok: false };
      const fitted = fitWithoutTrimming(base, prefix, [task, suffix].join("\n\n"), maxChars, 0, true, capacity);
      return { ...fitted, tokens };
    };
    let fitted = fit(chosen);
    // Retain the focus portrayal pair; if it cannot coexist with a whole task,
    // defer the assessment instead of delivering a partial contract.
    if (profiles.length) {
      chosen = [profiles[0]];
      fitted = fit(chosen);
    }
    // Preserve the exact delivered request across retries. Before first delivery,
    // shorten optional older evidence, never a partial contract.
    if (!fitted.ok && request.deliveryFrozen !== true) {
      if (request.cast) request.cast.showAliases = false;
      task = sceneAssessmentTask(request);
      fitted = fit(chosen);
      while (!fitted.ok && request.evidence.length > 1) {
        request.evidence.shift();
        if (request.time) request.time = timelineSceneRequest(request.evidence);
        task = sceneAssessmentTask(request);
        fitted = fit(chosen);
      }
    }
    // Reuse CC's existing complete compact portrayal tiers when full profiles
    // cannot share its configured budget with the Scene contract.
    if (!fitted.ok && profiles.length) {
      for (const tier of ["compact", "emergency"]) {
        profiles = wholePortrayalProfiles(active, focus, tier);
        chosen = [profiles[0]];
        fitted = fit(chosen);
        if (fitted.ok) { portrayalTier = tier; break; }
      }
    }
    plan.sceneRequest = clone(request);
    plan.evidenceIds = request.evidence.map(item => item.id);
    if (fitted.ok) fitted = extendWholePortrayal(chosen, profiles, fit, plan);
    const committed = fitted.ok ? commitContextSuffix(suffixInstruction, fitted.text) : null;
    if (!committed || !committed.ok || !committed.delivered
      || !committed.text.includes(task) || (maxChars && committed.text.length > maxChars)) {
      CC.sceneRecognition.lastResult = "Scene assessment deferred: its complete evidence, portrayal, and response contract did not fit.";
      CC.last.context = CC.sceneRecognition.lastResult;
      CC.last.gracefulFallback = true;
      return defer();
    }
    plan.sceneTaskDelivered = true;
    plan.sceneRequest.deliveryFrozen = true;
    plan.modelActiveKeys = chosen.filter(item => item.character).map(item => item.character.key);
    CC.modelActiveKeys = plan.modelActiveKeys.slice();
    Object.assign(CC.last, {
      task: "scene", owner: "Setting", context: "Setting is the sole assessment subject; a complete narrated-scene request was delivered.",
      injectedTokens: fitted.tokens, effectiveBudget: capacity.effectiveBudget,
      headroomTokens: Math.max(0, capacity.effectiveBudget - fitted.tokens),
      taskTokens: estimateTokens(task), portrayalTier,
      suppliedEvidence: request.evidence.map(item => item.id)
    });
    recordGenuineContextPlan(plan, "");
    return committed.text;
  }


  function parseSceneResponse(value, plan) {
    const raw = textOf(value).replace(/\r/g, "");
    const records = [];
    const story = raw.replace(/\([ \t]*CCSCENE\b[^\n)]*(?:\)|(?=\n|$))/gi, record => {
      records.push(record); return "";
    }).trim();
    if (!records.length) return { story, error: "The model omitted the requested CCSCENE record.", count: 0 };
    if (!runtime.sceneRecognition || !plan || plan.settingTurn !== true || plan.sceneTaskDelivered !== true || !plan.sceneRequest) {
      return { story, error: "An unsolicited CCSCENE record was stripped; no Scene update was authorized.", count: records.length };
    }
    const first = raw.trimStart().split("\n")[0].trim();
    if (records.length !== 1 || first !== records[0] || !first.endsWith(")")
      || /\([ \t]*(?:CCO|CCP|CCI)\b/i.test(raw)) {
      return { story, error: "Scene assessment requires one complete first-line CCSCENE record and no other continuity record.", count: records.length };
    }
    const parts = first.slice(1, -1).split("|").map(item => item.trim());
    const request = plan.sceneRequest;
    // A record without the two time fields still updates the Scene; only the
    // timer correction is skipped for it.
    const baseLength = request.cast ? 8 : 7;
    const timeOffset = request.time && parts.length === baseLength + 2 ? 2 : 0;
    if (parts.length !== baseLength + timeOffset || parts[0] !== "CCSCENE" || parts[1] !== request.id) {
      return { story, error: "The Scene record was malformed or belonged to another request.", count: 1 };
    }
    const ids = parts[2].split(",").map(item => item.trim());
    const suppliedIds = request.evidence.map(item => item.id);
    if (!ids.length || new Set(ids).size !== ids.length || ids.some(id => !/^E\d+$/.test(id) || !suppliedIds.includes(id))
      || !ids.includes(suppliedIds[suppliedIds.length - 1])
      || suppliedIds.filter(id => ids.includes(id)).join(",") !== ids.join(",")) {
      return { story, error: "The Scene record cited evidence outside its supplied ordered packet.", count: 1 };
    }
    if (!settings.SCENE_CHANGES.includes(parts[3])) return { story, error: "The Scene change classification was invalid.", count: 1 };
    const sceneTime = timeOffset ? timelineParseSceneTime(parts[4], parts[5], request) : null;
    const fields = { Occasion: parts[4 + timeOffset], Phase: parts[5 + timeOffset], "Unresolved beat": parts[6 + timeOffset] };
    for (const field of Object.keys(fields)) {
      const text = fields[field];
      const maximum = field === "Occasion" ? settings.MAX_SCENE_OCCASION_CHARS : settings.MAX_SCENE_BEAT_CHARS;
      if (!text || text.length > maximum || /[{}\[\]|()<>\r\n]/.test(text) || keyOf(text) === keyOf(field)) {
        return { story, error: "The Scene " + field + " field was empty, too long, unsafe, or an unfilled placeholder.", count: 1 };
      }
      if (text === "KEEP" && request.requiresFresh) {
        return { story, error: "The Scene needs a fresh assessment; stale fields cannot be kept automatically.", count: 1 };
      }
      if (text === "KEEP") fields[field] = request.baseline[field];
      else if (field === "Unresolved beat" && text === "NONE") fields[field] = "";
      else if (field === "Phase" && !settings.SCENE_PHASES.includes(text)) {
        return { story, error: "The Scene Phase was not Unfolding, Settling, or Ready for transition.", count: 1 };
      }
    }
    const cast = parseSceneCastResponse(parts[7 + timeOffset], request, parts[3]);
    if (!cast.ok) return { story, error: cast.error, count: 1 };
    if (request.cast) fields.Participants = cast.value;
    return { story, count: 1, candidate: { fields, change: parts[3], evidenceIds: ids, time: sceneTime }, error: "" };
  }


  function commitSceneAssessment(parsed, plan, generation) {
    CC.sceneRecognition.lastServedGeneration = generation;
    const request = plan.sceneRequest;
    let error = parsed.error;
    const scene = currentSceneCard();
    if (!error && !scene.ok) error = scene.error;
    if (!error && scene.entry !== request.baselineEntry) error = "Setting's Scene changed after the request; the newer creator entry was preserved.";
    if (!error && request.evidence.some(source => {
      const current = evidenceForId(source.id);
      if (!current || hashString(current.text) !== source.hash) return true;
      return source.complete === true && current.anchor
        && (source.text.length !== current.anchor.chars || hashString(source.text) !== current.anchor.hash);
    })) error = "The Scene assessment's source evidence changed or was discarded.";
    if (!error && request.cast && request.cast.signature !== sceneRosterSignature()) {
      error = "The registered NPC roster changed after the Scene request; participant identities were preserved.";
    }
    let changed = false;
    if (!error && parsed.candidate) {
      const rows = scene.rows.slice();
      Object.keys(parsed.candidate.fields).forEach(field => {
        const after = parsed.candidate.fields[field];
        if (scene.values[field] === after) return;
        changed = true;
        rows[scene.indexes[field]] = rows[scene.indexes[field]].replace(/(:)[ \t]*.*$/, ":" + (after ? " " + after : ""));
      });
      const entry = rows.join(scene.newline);
      const saved = changed ? saveCard(scene.card, entry, "Setting's Scene") : scene.card;
      if (!saved || entryOf(saved) !== entry) error = "The Scene card write did not persist; its prior content was preserved.";
      if (!error) {
        CC.sceneRecognition.lastCommittedEntry = entry;
        CC.sceneRecognition.lastChange = parsed.candidate.change;
        CC.sceneRecognition.lastAssessedEvidenceNumber = Math.max(...request.evidence.map(item => item.number));
        CC.sceneRecognition.needsReassessment = false;
        if (request.cast) CC.sceneRecognition.participantRosterSignature = request.cast.signature;
        if (parsed.candidate.time) applySceneTime(parsed.candidate.time, request);
      }
    }
    CC.sceneRecognition.lastResult = error || (changed ? "Scene updated" : "Scene assessed unchanged");
    CC.last.task = "scene";
    CC.last.owner = "Setting";
    CC.last.candidate = error ? "scene rejected" : (changed ? "scene accepted" : "scene unchanged");
    CC.last.protocol = error || "CCSCENE request and supplied evidence validated.";
    CC.last.error = error || "";
    CC.last.operationOutcome = error ? "Scene rejected" : (changed ? "Scene success" : "Scene unchanged");
    CC.last.operationDrainChange = "No NPC opportunity or drain change";
    CC.last.update = error ? "None" : CC.sceneRecognition.lastResult + ": "
      + (parsed.candidate.fields.Phase || "Unspecified") + " / " + parsed.candidate.change;
    CC.last.output = error ? "Story prose survived; the Scene update was withheld."
      : "Story prose survived and the narrated-scene assessment committed. No NPC operation was requested.";
  }


  function scenePortrayalRules() {
    return [
      "Use each supplied NPC's Outer/Inner as their baseline; apply relevant details and leave others latent. Not established yet means unknown. Inner supplies enduring tendencies; State temporary private pressure; Experiences established events. Preserve independent choices and distinct character knowledge.",
      "Relationships and Views run from owner to target. Use canonical names and permitted Active aliases; Emerging aliases are tentative, Retired historical, and Rejected declined.",
      turningPointPortrayalAuthorityRule(),
      "Only the Player controls their words, actions, thoughts, feelings, identity, consent, and commitments. Honor their input as established; leave their next response open.",
      "Player: " + player.name + " | " + [player.subject, player.object, player.possessiveAdjective, player.possessivePronoun, player.reflexive].join("/") + " | " + player.agreement
    ].join("\n");
  }

  function appendScenePacingContext(base, commitContextSuffix) {
    const pacing = scenePacingContext();
    if (!pacing) return commitContextSuffix("", base).text;
    const prefix = renderPortrayalComponents([{ text: pacing }]);
    const maximum = Number(typeof info !== "undefined" && info ? info.maxChars : 0) || 0;
    const capacity = continuityCapacity(base, maximum);
    const tokens = estimateTokens(prefix);
    if (tokens > capacity.effectiveBudget) return commitContextSuffix("", base).text;
    const fitted = fitWithoutTrimming(base, prefix, "", maximum, 0, true, capacity);
    if (!fitted.ok) return commitContextSuffix("", base).text;
    CC.last.injectedTokens = tokens;
    CC.last.effectiveBudget = capacity.effectiveBudget;
    return commitContextSuffix("", fitted.text).text;
  }

  function playerSetupPlaceholderRows() {
    const supplied = rootState && Array.isArray(rootState.placeholders)
      ? rootState.placeholders
      : [];
    return supplied.map(item => ({
      question: line(item && item.question, 1000),
      answer: line(item && item.answer, 1000)
    })).filter(item => item.question && item.answer);
  }

  function playerSetupQuestionKey(value) {
    return textOf(value).normalize("NFKC").toLowerCase()
      .replace(/[^a-z0-9.]+/g, " ").replace(/\s+/g, " ").trim();
  }

  function playerSetupAnswerFor(question, rows) {
    const wanted = playerSetupQuestionKey(question);
    if (!wanted) return "";
    const matches = (Array.isArray(rows) ? rows : [])
      .filter(item => playerSetupQuestionKey(item.question) === wanted);
    return matches.length === 1 ? line(matches[0].answer, 1000) : "";
  }

  function resolvePlayerSetupTokens(value, rows) {
    return textOf(value).replace(/\$\{([^{}\r\n]+)\}/g, (match, question) => {
      const answer = playerSetupAnswerFor(question, rows);
      return answer || match;
    });
  }

  function inferredPlayerPronouns(gender) {
    const normalized = playerSetupQuestionKey(gender);
    if (/^(?:female|woman|girl|feminine)$/.test(normalized)) return "she/her";
    if (/^(?:male|man|boy|masculine)$/.test(normalized)) return "he/him";
    if (/^(?:nonbinary|non binary|enby|agender|genderfluid|gender fluid)$/.test(normalized)) {
      return "they/them";
    }
    return "";
  }

  function playerSetupFromPlaceholders() {
    const rows = playerSetupPlaceholderRows();
    const classified = rows.map(item => ({
      ...item,
      key: playerSetupQuestionKey(item.question)
    }));
    const first = classified.find(item => /\b(?:first|given) name\b/.test(item.key));
    const family = classified.find(item => /\b(?:last|family) name\b|\bsurname\b/.test(item.key));
    const pronouns = classified.find(item => /\bpronouns?\b/.test(item.key));
    const generic = classified.find(item => {
      if (!/\bname\b/.test(item.key) && item.key !== "character.name") return false;
      return !/\b(?:first|given|last|family) name\b|\bsurname\b|\bnickname\b|\balias\b|\btitle\b/.test(item.key);
    });
    let name = "";
    let age = "";
    let gender = "";
    if (first || family) {
      name = [first && first.answer, family && family.answer].filter(Boolean).join(" ");
    } else if (generic) {
      const combined = /\bage\b/.test(generic.key) || /\bgender\b/.test(generic.key);
      const parts = combined
        ? generic.answer.split(/\s*,\s*/).map(value => line(value, 300)).filter(Boolean)
        : [generic.answer];
      name = line(parts[0], 300);
      age = line(parts[1], 120);
      gender = line(parts[2], 120);
    }
    const aliasCandidates = [
      first ? { value: first.answer, kind: "first-name" } : null,
      family ? { value: family.answer, kind: "family-name" } : null
    ].filter(item => item && item.value && !sameNameForm(item.value, name));
    return {
      rows,
      name: line(name, 300),
      age,
      gender,
      pronouns: line(pronouns && pronouns.answer, 300) || inferredPlayerPronouns(gender),
      aliases: aliasCandidates
    };
  }

  function playerIdentityTemplateValue(value) {
    const supplied = line(value, 1000);
    if (!supplied || /\$\{[^{}]+\}/.test(supplied)
      || /^\s*\[(?:replace|match)\b.*\]\s*$/i.test(supplied)
      || /[{}|\r\n]/.test(supplied)) return "";
    return supplied;
  }

  function playerIdentityTemplate(name, pronouns) {
    return [
      "{",
      "Player's Identity:",
      "Name: " + (name || "[replace]"),
      "Pronouns: " + (pronouns || "[replace]"),
      "}"
    ].join("\n");
  }

  function playerIdentityNotes() {
    return "These notes are instructions only; write Player data in Entry. Name is the Player character's complete canonical name. Pronouns may be she/her, he/him, they/them, or five custom forms in subject/object/possessive-adjective/possessive-pronoun/reflexive order. For a published Scenario, put AI Dungeon setup placeholders only in the Name and Pronouns lines in Entry; never put setup placeholder syntax in Notes. When this card is absent in an Adventure, CC can also recover common name and pronoun answers from state.placeholders.";
  }

  function replacePlayerIdentityField(source, label, value) {
    const rows = textOf(source).replace(/\r/g, "").split("\n");
    const pattern = new RegExp("^[ \\t]*" + escapeRegExp(label) + "[ \\t]*:", "i");
    const index = rows.findIndex(row => pattern.test(row));
    if (index >= 0) rows[index] = label + ": " + value;
    else {
      const closing = rows.map(row => row.trim()).lastIndexOf("}");
      rows.splice(closing >= 0 ? closing : rows.length, 0, label + ": " + value);
    }
    return rows.join("\n");
  }

  function playerProfile() {
    const setup = playerSetupFromPlaceholders();
    let card = findCard(settings.PLAYER_TITLE);
    if (!card) {
      card = addCard(
        settings.PLAYER_TITLE,
        playerIdentityTemplate(setup.name, setup.pronouns),
        playerIdentityNotes()
      );
    }
    let source = card ? entryOf(card) : "";
    const resolved = resolvePlayerSetupTokens(source, setup.rows);
    if (resolved !== source) source = resolved;
    const existingName = extractLine(source, "Name");
    const existingPronouns = extractLine(source, "Pronouns");
    if (!playerIdentityTemplateValue(existingName) && setup.name) {
      source = replacePlayerIdentityField(source, "Name", setup.name);
    }
    if (!playerIdentityTemplateValue(existingPronouns) && setup.pronouns) {
      source = replacePlayerIdentityField(source, "Pronouns", setup.pronouns);
    }
    if (card) card = saveCard(card, source, settings.PLAYER_TITLE) || card;
    source = card ? entryOf(card) : source;
    const suppliedName = playerIdentityTemplateValue(extractLine(source, "Name"));
    const suppliedPronouns = playerIdentityTemplateValue(extractLine(source, "Pronouns"));
    const name = suppliedName || setup.name || "the player";
    const raw = (suppliedPronouns || setup.pronouns || "they/them").split(/[\/|,;\s]+/).filter(Boolean);
    let forms;
    if (raw.length >= 5) forms = raw.slice(0, 5);
    else {
      const subject = keyOf(raw[0] || "they");
      if (subject === "she") forms = ["she", "her", "her", "hers", "herself"];
      else if (subject === "he") forms = ["he", "him", "his", "his", "himself"];
      else forms = ["they", "them", "their", "theirs", "themselves"];
    }
    return {
      name,
      aliases: [name],
      emergingAliases: [],
      setupAliases: setup.aliases,
      identityReady: !!suppliedName || !!setup.name,
      identityCardCreated: !!card,
      subject: forms[0], object: forms[1], possessiveAdjective: forms[2],
      possessivePronoun: forms[3], reflexive: forms[4],
      agreement: keyOf(forms[0]) === "they" ? "plural" : "singular"
    };
  }

  const player = playerProfile();

  function resolvePlayerTokens(value) {
    const forms = {
      name: player.name,
      subject: player.subject,
      object: player.object,
      possessive_adjective: player.possessiveAdjective,
      possessiveadjective: player.possessiveAdjective,
      possessive_pronoun: player.possessivePronoun,
      possessivepronoun: player.possessivePronoun,
      reflexive: player.reflexive,
      is: player.agreement === "plural" ? "are" : "is",
      has: player.agreement === "plural" ? "have" : "has",
      does: player.agreement === "plural" ? "do" : "does",
      was: player.agreement === "plural" ? "were" : "was",
      s: player.agreement === "plural" ? "" : "s"
    };
    return textOf(value).replace(/{{\s*(player|Player|PLAYER)\.([a-zA-Z_]+)\s*}}/g, (match, owner, field) => {
      const token = keyOf(field).replace(/\s+/g, "_");
      if (!Object.prototype.hasOwnProperty.call(forms, token)) return match;
      const replacement = forms[token];
      if (typeof replacement !== "string") return match;
      if (owner === "PLAYER") return textOf(replacement).toUpperCase();
      if (owner === "Player") return replacement ? replacement.charAt(0).toUpperCase() + replacement.slice(1) : replacement;
      return replacement;
    });
  }

  function normalizeCastStatus(value, fallback) {
    const normalized = keyOf(value);
    if (normalized === "main" || normalized === "side") return normalized;
    return fallback;
  }

  function parseOuterPronouns(source) {
    const parts = textOf(extractLine(source, "Name, age, gender, pronouns"))
      .split(",")
      .map(value => value.trim());
    // The field is "Name, age, gender, pronouns", so the pronouns are the fourth
    // value and everything after it belongs to them. Taking the LAST value instead
    // meant any trailing note -- "Snow, 31, woman, she/her, tall" -- was read as the
    // pronouns, and an unrecognised value silently falls back to they/them, so the
    // character was misgendered for the rest of the story.
    return line(parts.slice(3).join(", "), 120);
  }

  function shortenProfileValue(value, maximum) {
    const source = line(value, 20000);
    const max = Math.max(1, Number(maximum) || 1);
    if (source.length <= max) return source;
    if (max === 1) return "…";
    const candidate = source.slice(0, max - 1).trimEnd();
    const wordBreak = candidate.lastIndexOf(" ");
    const kept = wordBreak >= Math.floor(max * 0.55)
      ? candidate.slice(0, wordBreak)
      : candidate;
    return kept.replace(/[,:;\-/]+$/g, "").trimEnd() + "…";
  }

  function renderOuterBlock(name, fields) {
    return [
      "{",
      name + "'s Outer:",
      ...fields.map(field => field.label + ": " + field.value),
      "}"
    ].join("\n");
  }

  function outerWrapperStatus(source) {
    const trimmed = textOf(source).replace(/\r/g, "").trim();
    return {
      opening: trimmed.startsWith("{"),
      closing: trimmed.endsWith("}")
    };
  }

  // A roster-generated profile starts as a valid six-card CC character and is
  // refined by hidden model records over play. The marker distinguishes fields
  // CC may develop from established creator-authored anchors, which always win.
  function rosterManagedLine(source, label, maximum) {
    const match = textOf(source).replace(/\r/g, "").match(new RegExp(
      "^[ \\t]*" + escapeRegExp(label) + "[ \\t]*:[ \\t]*(.*?)[ \\t]*$",
      "im"
    ));
    return match ? line(match[1], maximum) : "";
  }

  function rosterManagedHashFromSource(source) {
    return rosterManagedLine(source, "Roster source", 120);
  }

  function rosterManagedProfileCard(card) {
    return !!(card && rosterManagedHashFromSource(entryOf(card)));
  }

  function rosterManagedModeFromSource(source) {
    const value = keyOf(rosterManagedLine(source, "Roster source mode", 120));
    return value === "progressive" ? "Progressive" : "Six-card";
  }

  function buildOuterProfile(name, source) {
    const resolved = resolvePlayerTokens(source);
    const fields = [
      { label: "Name, age, gender, pronouns", value: extractLine(resolved, "Name, age, gender, pronouns") },
      { label: "Race/Species", value: extractLine(resolved, "Race/Species") },
      { label: "Physical attributes", value: extractLine(resolved, "Physical attributes") },
      { label: "Clothing style", value: extractLine(resolved, "Clothing style") }
    ].map(field => ({ label: field.label, value: line(field.value, 20000) }));
    const original = renderOuterBlock(name, fields);
    const maximum = settings.MAX_OUTER_CARD_CHARS;
    const fitted = fields.map(field => ({ label: field.label, value: field.value }));
    let rendered = original;
    let guard = 0;
    while (rendered.length > maximum && guard < 40) {
      guard += 1;
      const candidates = fitted.map((field, index) => ({
        index,
        reducible: Math.max(0, field.value.length - 24)
      })).filter(item => item.reducible > 0)
        .sort((left, right) => right.reducible - left.reducible || left.index - right.index);
      if (!candidates.length) break;
      const selected = candidates[0];
      const overflow = rendered.length - maximum;
      const reduction = Math.min(selected.reducible, Math.max(1, overflow));
      fitted[selected.index].value = shortenProfileValue(
        fitted[selected.index].value,
        fitted[selected.index].value.length - reduction
      );
      rendered = renderOuterBlock(name, fitted);
    }
    if (rendered.length > maximum) rendered = wrappedLine(rendered, maximum);
    return {
      text: rendered,
      originalChars: original.length,
      retainedChars: rendered.length,
      truncated: original.length > rendered.length,
      missing: fields.filter(field => !field.value).map(field => field.label)
    };
  }

  function renderInnerBlock(name, fields) {
    return [
      "{",
      name + "'s Inner:",
      ...fields.map(field => field.label + ": " + field.value),
      "}"
    ].join("\n");
  }

  function buildInnerProfile(name, source) {
    const resolved = resolvePlayerTokens(source);
    const fields = [
      { label: "Personality", value: extractLine(resolved, "Personality") },
      { label: "Mannerisms", value: extractLine(resolved, "Mannerisms") },
      { label: "Wants", value: extractLine(resolved, "Wants") },
      { label: "Fears", value: extractLine(resolved, "Fears") },
      { label: "Mental wounds", value: extractLine(resolved, "Mental wounds") },
      { label: "Principles", value: extractLine(resolved, "Principles") }
    ].map(field => ({ label: field.label, value: line(field.value, 20000) }));
    const original = renderInnerBlock(name, fields);
    const maximum = settings.MAX_INNER_CARD_CHARS;
    const fitted = fields.map(field => ({ label: field.label, value: field.value }));
    let rendered = original;
    let guard = 0;
    while (rendered.length > maximum && guard < 60) {
      guard += 1;
      const candidates = fitted.map((field, index) => ({
        index,
        reducible: Math.max(0, field.value.length - 24)
      })).filter(item => item.reducible > 0)
        .sort((left, right) => right.reducible - left.reducible || left.index - right.index);
      if (!candidates.length) break;
      const selected = candidates[0];
      const overflow = rendered.length - maximum;
      const reduction = Math.min(selected.reducible, Math.max(1, overflow));
      fitted[selected.index].value = shortenProfileValue(
        fitted[selected.index].value,
        fitted[selected.index].value.length - reduction
      );
      rendered = renderInnerBlock(name, fitted);
    }
    if (rendered.length > maximum) rendered = wrappedLine(rendered, maximum);
    return {
      text: rendered,
      originalChars: original.length,
      retainedChars: rendered.length,
      truncated: original.length > rendered.length,
      missing: fields.filter(field => !field.value).map(field => field.label)
    };
  }

  const activeRosterDiagnostics = [];
  const rosterImportCandidates = [];

  function activeNpcSlotCode(number) {
    const slot = Number(number);
    return Number.isSafeInteger(slot) && slot >= 1 && slot <= settings.MAX_ROSTER_NPCS
      ? "N" + slot
      : "";
  }

  function canonicalNpcSlotCode(value) {
    const match = textOf(value).trim().match(/^N([1-9]\d*)$/i);
    return match ? activeNpcSlotCode(Number(match[1])) : "";
  }

  function canonicalOperationRouteCode(value) {
    const supplied = textOf(value).trim().toUpperCase();
    return supplied === "S" || supplied === "P" ? supplied : canonicalNpcSlotCode(supplied);
  }

  function legacyActiveNpcRosterNotes() {
    return "Enter each NPC's canonical name in N1–N" + settings.MAX_ROSTER_NPCS
      + ". Roster entries make characters available; Maximum active NPCs in CC — Settings controls how many relevant NPCs are selected per turn, up to "
      + settings.MAX_ACTIVE_NPCS
      + ". New profiles activate automatically and fill from existing character information and established play. Unknowns remain Not established yet. You can fill or edit fields yourself. When the core profile is complete, delete its CC completion notice from the output before continuing gameplay.";
  }


  function activeNpcRosterNotes() {
    return "Enter each NPC's canonical name in N1–N" + settings.MAX_ROSTER_NPCS
      + ". Roster entries make characters available; Maximum active NPCs in CC — Settings controls how many relevant NPCs are selected per turn, up to "
      + settings.MAX_ACTIVE_NPCS
      + ". Scene-based NPC activation selects confirmed scene participants; off-scene characters keep their identities and saved cards. New profiles become available automatically and fill from existing character information and established play. Unknowns remain Not established yet. You can fill or edit fields yourself. When the core profile is complete, delete its CC completion notice from the output before continuing gameplay.";
  }

  function expandLegacyActiveNpcRoster(card) {
    const source = entryOf(card);
    const rows = textOf(source).replace(/\r/g, "").split("\n");
    const nonempty = rows.map((row, index) => ({ row: row.trim(), index })).filter(item => item.row);
    if (nonempty.length < 2 || nonempty[0].row !== "{"
      || nonempty[nonempty.length - 1].row !== "}") return card;
    const counts = Array.from({ length: settings.MAX_ROSTER_NPCS }, (_, index) => {
      const pattern = new RegExp("^[ \\t]*N" + (index + 1) + "[ \\t]*:", "i");
      return rows.filter(row => pattern.test(row)).length;
    });
    // v3.0.17 used N1–N5. Preserve malformed/duplicate rows for normal diagnostics;
    // only add missing extension slots to a complete, unambiguous legacy layout.
    if (counts.slice(0, 5).some(count => count !== 1) || counts.some(count => count > 1)) return card;
    const missing = counts.map((count, index) => index >= 5 && count === 0 ? "N" + (index + 1) + ": " : "")
      .filter(Boolean);
    if (!missing.length) return card;
    rows.splice(nonempty[nonempty.length - 1].index, 0, ...missing);
    const saved = saveCard(card, rows.join("\n"), settings.ACTIVE_NPCS_TITLE);
    if (!saved) {
      activeRosterDiagnostics.push("CC — Active NPCs could not be expanded; its existing slots were preserved.");
      return card;
    }
    activeRosterDiagnostics.push("CC — Active NPCs gained " + missing.length
      + " empty roster slots; existing names and slot numbers were preserved.");
    return saved;
  }

  function activeNpcRosterEntry(slotNames) {
    const names = Array.isArray(slotNames) ? slotNames : [];
    const rows = ["{", "Active NPC slots:"];
    for (let index = 0; index < settings.MAX_ROSTER_NPCS; index++) {
      rows.push(activeNpcSlotCode(index + 1) + ": " + line(names[index], 120));
    }
    rows.push("}");
    return rows.join("\n");
  }

  function activeNpcRosterName(value) {
    const source = textOf(value).trim();
    if (!source || source.length > 120 || /[{}\[\]|\r\n]/.test(source)) return "";
    return line(source, 120);
  }

  function readActiveNpcRoster() {
    const matching = catalogRecordsByTitle(settings.ACTIVE_NPCS_TITLE)
      .map(record => record.card);
    let card = matching[0] || null;
    const slots = Array.from({ length: settings.MAX_ROSTER_NPCS }, (_, index) => ({
      number: index + 1,
      code: activeNpcSlotCode(index + 1),
      name: "",
      valid: true
    }));
    if (!card) return { card: null, slots, source: "", wrapperValid: true };
    if (matching.length > 1) {
      activeRosterDiagnostics.push("Multiple CC — Active NPCs cards were found; only the first is authoritative.");
    }
    if (textOf(card.type) !== settings.CARD_TYPE
      || !managedCardIdentityMatches(card, settings.ACTIVE_NPCS_TITLE)) {
      const updated = saveCard(card, entryOf(card), settings.ACTIVE_NPCS_TITLE);
      if (updated) card = updated;
      else activeRosterDiagnostics.push("CC — Active NPCs could not be internalized as a Continuity card.");
    }
    card = expandLegacyActiveNpcRoster(card);
    const legacyNotes = "Enter each NPC's canonical name in N1–N5. New profiles activate automatically and fill from existing character information and established play. Unknowns remain Not established yet. You can fill or edit fields yourself. When the core profile is complete, delete its CC completion notice from the output before continuing gameplay.";
    if (!notesOf(card).trim() || notesOf(card) === legacyNotes || notesOf(card) === legacyActiveNpcRosterNotes()) {
      card = restoreCardNotes(card, activeNpcRosterNotes()) || card;
    }
    const source = entryOf(card);
    const trimmed = textOf(source).replace(/\r/g, "").trim();
    const wrapperValid = trimmed.startsWith("{") && trimmed.endsWith("}");
    if (!wrapperValid) activeRosterDiagnostics.push("CC — Active NPCs wrapper { } is incomplete.");
    const rows = textOf(source).replace(/\r/g, "").split("\n");
    slots.forEach(slot => {
      const pattern = new RegExp("^[ \\t]*" + escapeRegExp(slot.code) + "[ \\t]*:[ \\t]*(.*?)[ \\t]*$", "i");
      const matches = rows.map(row => row.match(pattern)).filter(Boolean);
      if (matches.length !== 1) {
        slot.valid = false;
        activeRosterDiagnostics.push(slot.code + " must appear exactly once in CC — Active NPCs.");
        return;
      }
      const supplied = textOf(matches[0][1]).trim();
      if (!supplied) return;
      const name = activeNpcRosterName(supplied);
      if (!name || name !== supplied) {
        slot.valid = false;
        activeRosterDiagnostics.push(slot.code + " contained an invalid or overlong canonical NPC name.");
        return;
      }
      slot.name = name;
    });
    rows.forEach(row => {
      const match = row.match(/^[ \t]*N(\d+)[ \t]*:/i);
      if (match && !activeNpcSlotCode(Number(match[1]))) {
        activeRosterDiagnostics.push("Unsupported active NPC slot N" + Number(match[1]) + " was ignored.");
      }
    });
    const seen = Object.create(null);
    slots.forEach(slot => {
      if (!slot.valid || !slot.name) return;
      const key = nameKeyOf(slot.name);
      if (seen[key]) {
        slot.valid = false;
        activeRosterDiagnostics.push(slot.code + " duplicated " + seen[key] + " and was ignored without compacting the roster.");
      } else seen[key] = slot.code;
    });
    return { card, slots, source, wrapperValid };
  }

  function onboardingMarkerPresent(source) {
    return /^[ \t]*Onboarding[ \t]*:[ \t]*Pending[ \t]*$/im.test(textOf(source));
  }

  const ONBOARDING_VIEW_CATEGORIES = ["Loves", "Likes", "Neutrals", "Dislikes", "Hates"];
  const ONBOARDING_RELATIONSHIP_FIELDS = ["Role", "Trust", "Closeness", "Boundaries", "Conflict"];
  const ONBOARDING_RELATIONSHIP_STAGES = {
    Role: [
