  ];

  const IMPORT_SECTION_CODES = [
    "OUTER", "INNER", "NAMES", "VIEWS", "RELATIONSHIPS", "EXPERIENCES"
  ];
  const IMPORT_STAGING_KEY_PREFIX = "§CCI-PENDING§";

  function importSectionTitle(name, section) {
    const labels = {
      OUTER: settings.OUTER_CHARACTER_LABEL,
      INNER: settings.INNER_CHARACTER_LABEL,
      NAMES: settings.NAMES_LABEL,
      VIEWS: settings.VIEWS_LABEL,
      RELATIONSHIPS: settings.RELATIONSHIPS_LABEL,
      EXPERIENCES: settings.EXPERIENCES_LABEL
    };
    return labels[section] ? namedTitle(name, labels[section]) : "";
  }

  function importStagingCardKey(title) {
    const logicalTitle = line(title, 220);
    return logicalTitle ? IMPORT_STAGING_KEY_PREFIX + encodedManagedTitle(logicalTitle) : "";
  }

  function importStagingCard(card, expectedTitle = "") {
    if (!card || !textOf(card.keys).startsWith(IMPORT_STAGING_KEY_PREFIX)) return false;
    const title = line(expectedTitle || titleOf(card), 220);
    return !!(title
      && textOf(card.keys) === importStagingCardKey(title)
      && titleKeyOf(rawVisibleTitleOf(card)) === titleKeyOf(title)
      && textOf(card.type) === settings.CARD_TYPE
      && titleKeyOf(managedTitleFromEntry(card)) === titleKeyOf(title));
  }

  function importNameMentioned(value, name) {
    const wanted = line(name, 160);
    if (!wanted) return false;
    const normalized = textOf(value).normalize("NFKC")
      .replace(/[‘’‛]/g, "'")
      .replace(/[‐‑‒–—―]/g, "-");
    const pattern = wanted.normalize("NFKC")
      .replace(/[‘’‛]/g, "'")
      .replace(/[‐‑‒–—―]/g, "-")
      .split(/\s+/).map(escapeRegExp).join("\\s+");
    return new RegExp("(^|[^A-Za-z0-9])" + pattern + "(?=$|[^A-Za-z0-9])", "i")
      .test(normalized);
  }

  function importSourceCardMatches(name) {
    const canonical = line(name, 160);
    return currentCardCatalog().records.map(record => {
      const card = record.card;
      if (!card || cardOwnedByContinuity(card)) return null;
      const visible = line(rawVisibleTitleOf(card), 220);
      if (!visible || defaultScriptCardTitle(visible)) return null;
      const titleDirect = sameNameForm(visible, canonical);
      const legacyDirect = visible.startsWith("@")
        && sameNameForm(visible.slice(1).trim(), canonical);
      const triggerDirect = textOf(card.keys).split(/[,;\n]/)
        .map(value => line(value, 160)).some(value => sameNameForm(value, canonical));
      const titleMention = importNameMentioned(visible, canonical);
      const entryMention = importNameMentioned(entryOf(card), canonical);
      if (!titleDirect && !legacyDirect && !triggerDirect && !titleMention && !entryMention) return null;
      const rank = titleDirect ? 0 : (legacyDirect ? 1 : (triggerDirect ? 2 : (titleMention ? 3 : 4)));
      const type = keyOf(card.type);
      const typeRank = type === "character" || type === "npc" ? 0 : 1;
      return { card, index: record.index, visible, rank, typeRank };
    }).filter(Boolean).sort((left, right) =>
      left.rank - right.rank || left.typeRank - right.typeRank || left.index - right.index
    );
  }

  function importContextExcerpts(contextValue, name) {
    const source = textOf(contextValue).replace(/\r/g, "");
    const wanted = line(name, 160);
    if (!source || !wanted) return "";
    const pattern = new RegExp(
      "(^|[^A-Za-z0-9])(" + wanted.split(/\s+/).map(escapeRegExp).join("\\s+")
        + ")(?=$|[^A-Za-z0-9])",
      "gi"
    );
    const windows = [];
    let match;
    while ((match = pattern.exec(source)) && windows.length < 8) {
      const start = Math.max(0, match.index - 420);
      const end = Math.min(source.length, pattern.lastIndex + 620);
      const prior = windows[windows.length - 1];
      if (prior && start <= prior.end + 80) prior.end = Math.max(prior.end, end);
      else windows.push({ start, end });
      if (pattern.lastIndex === match.index) pattern.lastIndex += 1;
    }
    const excerpts = windows.map(window => clean(source.slice(window.start, window.end), 1600));
    return compactLineAtBoundary(excerpts.join("\n…\n"), settings.MAX_IMPORT_CONTEXT_CHARS);
  }

  function rosterImportSourceInfo(name, contextValue) {
    const matches = importSourceCardMatches(name);
    const rows = [];
    let used = 0;
    matches.forEach(item => {
      if (used >= settings.MAX_IMPORT_CARD_CHARS) return;
      const entry = clean(entryOf(item.card), settings.MAX_IMPORT_CARD_CHARS);
      const block = [
        "CARD " + (item.visible || "Untitled"),
        "Type: " + line(item.card.type, 80),
        "Triggers: " + line(item.card.keys, 240),
        "Entry: " + entry
      ].join("\n");
      const remaining = settings.MAX_IMPORT_CARD_CHARS - used;
      const fitted = block.length <= remaining ? block : compactLineAtBoundary(block, remaining);
      if (fitted) {
        rows.push(fitted);
        used += fitted.length;
      }
    });
    const context = importContextExcerpts(contextValue, name);
    const packet = clean([
      rows.join("\n\n"),
      context ? "CONTEXT EXCERPTS\n" + context : ""
    ].filter(Boolean).join("\n\n"), settings.MAX_IMPORT_SOURCE_CHARS);
    return {
      packet,
      titles: matches.map(item => item.visible).slice(0, 8),
      cardHash: hashString([
        "source-compiler",
        line(name, 160),
        ...matches.map(item => [
          rawVisibleTitleOf(item.card), textOf(item.card.keys), textOf(item.card.type), entryOf(item.card)
        ].join("\u241e"))
      ].join("\u241f"))
    };
  }

  const DEVELOPMENT_PLACEHOLDER = "Not established yet";
  const DEVELOPMENT_FIELDS = [
    { code: "IDENTITY", domain: "Outer", label: "Name, age, gender, pronouns", concrete: true },
    { code: "SPECIES", domain: "Outer", label: "Race/Species", concrete: true },
    { code: "APPEARANCE", domain: "Outer", label: "Physical attributes", concrete: true },
    { code: "CLOTHING", domain: "Outer", label: "Clothing style", concrete: true },
    { code: "STATUS", domain: "Outer", label: "Starting status", concrete: true },
    { code: "PERSONALITY", domain: "Inner", label: "Personality", concrete: false },
    { code: "MANNERISMS", domain: "Inner", label: "Mannerisms", concrete: false },
    { code: "WANTS", domain: "Inner", label: "Wants", concrete: false },
    { code: "FEARS", domain: "Inner", label: "Fears", concrete: false },
    { code: "WOUNDS", domain: "Inner", label: "Mental wounds", concrete: false },
    { code: "PRINCIPLES", domain: "Inner", label: "Principles", concrete: false }
  ];
  const DEVELOPMENT_FIELD_BY_CODE = DEVELOPMENT_FIELDS.reduce((result, field) => {
    result[field.code] = field;
    return result;
  }, {});

  function rosterSourceCardInfo(name) {
    const canonical = line(name, 220);
    return {
      mode: "Progressive",
      sourceHash: hashString("progressive-roster\u241f" + canonical)
    };
  }

  function rosterOuterEntry(name, sourceInfo) {
    return [
      "{",
      name + "'s Outer:",
      "Roster source: " + sourceInfo.sourceHash,
      "Roster source mode: Progressive",
      "Name, age, gender, pronouns: " + name + ", age not established yet, gender not established yet, pronouns not established yet",
      "Race/Species: " + DEVELOPMENT_PLACEHOLDER,
      "Physical attributes: " + DEVELOPMENT_PLACEHOLDER,
      "Clothing style: " + DEVELOPMENT_PLACEHOLDER,
      "Starting status: Side",
      "}"
    ].join("\n");
  }

  function rosterInnerEntry(name, sourceInfo) {
    return [
      "{",
      name + "'s Inner:",
      "Roster source: " + sourceInfo.sourceHash,
      "Roster source mode: Progressive",
      "Personality: " + DEVELOPMENT_PLACEHOLDER,
      "Mannerisms: " + DEVELOPMENT_PLACEHOLDER,
      "Wants: " + DEVELOPMENT_PLACEHOLDER,
      "Fears: " + DEVELOPMENT_PLACEHOLDER,
      "Mental wounds: " + DEVELOPMENT_PLACEHOLDER,
      "Principles: " + DEVELOPMENT_PLACEHOLDER,
      "}"
    ].join("\n");
  }

  function rosterNamesEntry(name) {
    return ["{", name + "'s Names:", "Canonical: " + name, "}"].join("\n");
  }

  function rosterEmptyRelationshipsEntry(name) {
    return ["{", name + "'s Relationships:", "}"].join("\n");
  }

  function rosterEmptyExperiencesEntry(name) {
    return ["{", name + "'s Experiences:", "}"].join("\n");
  }


  function progressiveUnknownValue(value) {
    const supplied = textOf(value).trim();
    return onboardingTemplatePlaceholder(supplied)
      || /^(?:(?:age|gender|pronouns?)\s+)?(?:not\s+(?:yet\s+)?(?:established|known|specified)(?:\s+yet)?|unknown|developing(?: from established play)?|tbd)[.!]?$/i.test(supplied);
  }

  function progressiveIdentityParts(value) {
    const parts = textOf(value).split(",").map(item => item.trim());
    return [parts[0] || "", parts[1] || "", parts[2] || "", parts.slice(3).join(", ")];
  }

  // Convert only our own pending/progressive static cards. Preserve authored
  // values, optional extra rows, notes, and every existing dynamic card.
  function progressiveProfileEntry(name, domain, card, sourceInfo) {
    if (!card) return domain === "Outer"
      ? rosterOuterEntry(name, sourceInfo) : rosterInnerEntry(name, sourceInfo);
    let source = entryOf(card);
    if (!onboardingProfileHeaderValid(source, name, domain)) {
      throw new Error(domain + " has an invalid owner wrapper");
    }
    source = onboardingWithoutControls(source);
    if (domain === "Outer") {
      const combined = onboardingFieldRows(source, "Name, age, gender, pronouns");
      const labels = ["Canonical name", "Age", "Gender", "Pronouns"];
      const split = labels.map(label => onboardingFieldRows(source, label));
      const hasSplit = split.some(rows => rows.length);
      if (combined.length > 1 || (combined.length && hasSplit)
        || split.some(rows => rows.length > 1)) throw new Error("Outer identity is ambiguous");
      const parts = hasSplit
        ? split.map(rows => rows[0] ? rows[0].value : "")
        : progressiveIdentityParts(combined[0] ? combined[0].value : "");
      if (!progressiveUnknownValue(parts[0]) && !sameNameForm(parts[0], name)) {
        throw new Error("Outer identity must retain the canonical name " + name);
      }
      parts[0] = name;
      ["age", "gender", "pronouns"].forEach((label, index) => {
        if (progressiveUnknownValue(parts[index + 1])) parts[index + 1] = label + " not established yet";
      });
      if (hasSplit) source = onboardingCanonicalOuterEntry(source, { mode: "split", parts, errors: [] });
      else if (combined.length) source = replaceDevelopmentField(source, "Name, age, gender, pronouns", parts.join(", "));
      else {
        const rows = source.split("\n");
        rows.splice(2, 0, "Name, age, gender, pronouns: " + parts.join(", "));
        source = rows.join("\n");
      }
    }
    for (const field of DEVELOPMENT_FIELDS.filter(item => item.domain === domain)) {
      const matches = onboardingFieldRows(source, field.label);
      if (matches.length > 1) throw new Error(domain + " repeats " + field.label);
      const prior = matches[0] ? matches[0].value : "";
      let value = progressiveUnknownValue(prior) ? DEVELOPMENT_PLACEHOLDER : prior;
      if (field.code === "STATUS") {
        if (!progressiveUnknownValue(prior) && !normalizeCastStatus(prior, "")) {
          throw new Error("Starting status must be Main or Side");
        }
        value = progressiveUnknownValue(prior) ? "Side" : prior;
      }
      if (matches.length) source = replaceDevelopmentField(source, field.label, value);
      else {
        const rows = source.split("\n");
        rows.splice(rows.findIndex(row => row.trim() === "}"), 0, field.label + ": " + value);
        source = rows.join("\n");
      }
    }
    const rows = source.split("\n").filter(row => !/^\s*Roster source(?: mode)?\s*:/i.test(row));
    rows.splice(2, 0, "Roster source: " + sourceInfo.sourceHash, "Roster source mode: Progressive");
    return rows.join("\n");
  }

  function ensureRosterProfile(slot, sourceInfo) {
    const labels = [settings.OUTER_CHARACTER_LABEL, settings.INNER_CHARACTER_LABEL,
      settings.NAMES_LABEL, settings.VIEWS_LABEL, settings.RELATIONSHIPS_LABEL, settings.EXPERIENCES_LABEL];
    const groups = labels.map(label => ({ label, title: namedTitle(slot.name, label),
      cards: onboardingExactCards(namedTitle(slot.name, label)) }));
    if (groups.some(group => group.cards.length > 1)) {
      return { handled: true, ok: false, error: "conflicting canonical cards must be resolved first" };
    }
    if (groups.some(group => group.cards[0]
      && !onboardingProfileHeaderValid(entryOf(group.cards[0]), slot.name, group.label))) {
      return { handled: true, ok: false, error: "a canonical card has an invalid owner wrapper; its contents were preserved" };
    }
    const existingOuter = groups[0].cards[0] || null;
    const existingInner = groups[1].cards[0] || null;
    const pending = [existingOuter, existingInner].some(card => card && onboardingMarkerPresent(entryOf(card)));
    const progressive = card => card && rosterManagedProfileCard(card)
      && rosterManagedModeFromSource(entryOf(card)) === "Progressive";
    if (!pending && [existingOuter, existingInner].some(card => card && !progressive(card))) {
      return { handled: false, ok: true };
    }
    const firstMaterialization = groups.every(group => !group.cards.length);
    let snapshot = null;
    try {
      const entries = [
        progressiveProfileEntry(slot.name, "Outer", existingOuter, sourceInfo),
        progressiveProfileEntry(slot.name, "Inner", existingInner, sourceInfo),
        rosterNamesEntry(slot.name), onboardingViewsTemplate(slot.name),
        rosterEmptyRelationshipsEntry(slot.name), rosterEmptyExperiencesEntry(slot.name)
      ];
      if (entries[0].length > settings.MAX_OUTER_CARD_CHARS
        || entries[1].length > settings.MAX_INNER_CARD_CHARS) {
        throw new Error("the progressive profile exceeds its storage limit; authored text was preserved");
      }
      const changed = groups.some((group, index) => !group.cards.length
        || (index < 2 && entryOf(group.cards[0]) !== entries[index]));
      if (!changed) return { handled: true, ok: true };
      snapshot = capturePhysicalCardDeck();
      groups.forEach((group, index) => {
        const current = group.cards[0] || null;
        // Existing Names/Views/Relationships/Experiences always win.
        if (current && index >= 2) return;
        const entry = entries[index];
        const saved = current ? saveCard(current, entry, group.title) : addCard(group.title, entry);
        if (!saved || entryOf(saved) !== entry || !managedCardIdentityMatches(saved, group.title)) {
          throw new Error("could not save " + group.title);
        }
        if (current && pending && notesOf(current) === onboardingCardNotes(group.label, slot.name)) {
          restoreCardNotes(saved, "Unknown fields remain Not established yet until supported by character information or play. You may edit any field; authored values take priority.");
        }
      });
    } catch (error) {
      const restored = !snapshot || restorePhysicalCardDeck(snapshot);
      return { handled: true, ok: false, error: (error.message || "roster activation failed")
        + (restored ? "" : "; rollback was incomplete") };
    }
    if (firstMaterialization || pending) activeRosterDiagnostics.push(
      slot.name + " activated for progressive development; existing details were preserved and unknown fields await evidence."
    );
    return { handled: true, ok: true };
  }

  function tryRosterNameActivation(slot) {
    const result = ensureRosterProfile(slot, rosterSourceCardInfo(slot.name));
    if (!result.handled) return false;
    if (!result.ok) {
      slot.valid = false;
      activeRosterDiagnostics.push(slot.name + " could not activate from the roster: " + result.error + ".");
    }
    return true;
  }

  function onboardingFieldRows(source, label) {
    const pattern = new RegExp(
      "^[ \\t]*" + escapeRegExp(label) + "[ \\t]*:[ \\t]*(.*?)[ \\t]*$",
      "i"
    );
    return textOf(source).replace(/\r/g, "").split("\n")
      .map((row, index) => {
        const match = row.match(pattern);
        return match ? { index, value: line(match[1], 4000) } : null;
      })
      .filter(Boolean);
  }

  function onboardingReadyValue(source) {
    const matches = onboardingFieldRows(source, "Ready");
    if (matches.length !== 1) return "";
    const normalized = keyOf(matches[0].value);
    return normalized === "yes" || normalized === "no" ? normalized : "";
  }

  function onboardingProfileHeaderValid(source, name, label) {
    return ownedEntryWrapperInfo(source, name, label).valid;
  }

  function onboardingTemplatePlaceholder(value) {
    const supplied = line(value, 4000);
    return !supplied || /^\s*\[(?:replace|main\s+or\s+side)\b.*\]\s*$/i.test(supplied);
  }

  function onboardingOuterIdentity(source, name) {
    const combined = onboardingFieldRows(source, "Name, age, gender, pronouns");
    const labels = ["Canonical name", "Age", "Gender", "Pronouns"];
    const split = labels.reduce((result, label) => {
      result[label] = onboardingFieldRows(source, label);
      return result;
    }, Object.create(null));
    const hasSplit = labels.some(label => split[label].length > 0);
    const errors = [];
    let parts = [];
    let mode = "";
    if (combined.length && hasSplit) {
      errors.push("Outer must use either the four identity sub-fields or the combined identity line, not both");
    } else if (hasSplit) {
      mode = "split";
      labels.forEach(label => {
        if (split[label].length !== 1 || onboardingTemplatePlaceholder(split[label][0] && split[label][0].value)) {
          errors.push("Outer requires one filled " + label + " line");
        }
      });
      parts = labels.map(label => split[label][0] ? split[label][0].value : "");
      if (parts[0] && !sameNameForm(parts[0], name)) {
        errors.push("Outer Canonical name must remain " + name);
      }
    } else {
      mode = "combined";
      parts = combined.length === 1
        ? combined[0].value.split(",").map(value => value.trim())
        : [];
      if (combined.length !== 1 || parts.length < 4
        || parts.slice(0, 4).some(onboardingTemplatePlaceholder)) {
        errors.push("Outer identity needs name, age, gender, and pronouns");
      } else if (!sameNameForm(parts[0], name)) {
        errors.push("Outer identity name must match the canonical owner " + name);
      }
    }
    return { mode, parts: parts.slice(0, 4), errors };
  }

  function onboardingCanonicalOuterEntry(source, identity) {
    const stripped = onboardingWithoutControls(source);
    if (!identity || identity.mode !== "split" || identity.errors.length) return stripped;
    const labels = new Set(["canonical name", "age", "gender", "pronouns"]);
    const rows = stripped.replace(/\r/g, "").split("\n");
    let insertion = -1;
    const kept = [];
    rows.forEach(row => {
      const match = row.match(/^[ \t]*([^:]+?)[ \t]*:/);
      if (match && labels.has(keyOf(match[1]))) {
        if (insertion < 0) insertion = kept.length;
        return;
      }
      kept.push(row);
    });
    const position = insertion < 0 ? Math.min(2, kept.length) : insertion;
    kept.splice(position, 0,
      "Name, age, gender, pronouns: " + identity.parts.join(", "));
    return kept.join("\n");
  }

  function onboardingMissingDetails(outerSource, innerSource, innerConflict) {
    const missing = [];
    const outerWrapper = outerWrapperStatus(outerSource);
    if (!outerWrapper.opening || !outerWrapper.closing) missing.push("Outer wrapper { }");
    const owner = ownedCardTitleParts(managedTitleFromEntry({ entry: outerSource }));
    const identity = onboardingOuterIdentity(outerSource, owner ? owner.owner : "");
    if (identity.errors.length) missing.push(identity.errors[0]);
    ["Race/Species", "Physical attributes", "Clothing style"].forEach(label => {
      if (onboardingTemplatePlaceholder(extractLine(outerSource, label))) missing.push(label);
    });
    if (!normalizeCastStatus(extractLine(outerSource, "Starting status"), "")) {
      missing.push("Starting status");
    }
    if (innerConflict) missing.push("one unambiguous Inner card");
    else if (!innerSource) missing.push("Inner card");
    else {
      const innerWrapper = outerWrapperStatus(innerSource);
      if (!innerWrapper.opening || !innerWrapper.closing) missing.push("Inner wrapper { }");
      ["Personality", "Mannerisms", "Wants", "Fears", "Mental wounds", "Principles"].forEach(label => {
        if (onboardingTemplatePlaceholder(extractLine(innerSource, label))) missing.push(label);
      });
    }
    return missing;
  }

  function onboardingOuterTemplate(name) {
    return [
      "{",
      name + "'s Outer:",
      "Onboarding: Pending",
      "Ready: No",
      "Canonical name: " + name,
      "Age: [replace]",
      "Gender: [replace]",
      "Pronouns: [replace]",
      "Race/Species: [replace]",
      "Physical attributes: [replace]",
      "Clothing style: [replace]",
      "Starting status: [Main or Side]",
      "}"
    ].join("\n");
  }

  function onboardingInnerTemplate(name) {
    return [
      "{",
      name + "'s Inner:",
      "Onboarding: Pending",
      "Personality: [replace]",
      "Mannerisms: [replace]",
      "Wants: [replace]",
      "Fears: [replace]",
      "Mental wounds: [replace]",
      "Principles: [replace]",
      "}"
    ].join("\n");
  }

  function onboardingNamesTemplate(name) {
    return [
      "{",
      name + "'s Names:",
      "Canonical: " + name,
      "",
      "Alias:",
      "Status:",
      "Use:",
      "Progress:",
      "Reason:",
      "}"
    ].join("\n");
  }

  function onboardingViewsTemplate(name) {
    return [
      "{",
      name + "'s Views:",
      "Loves:",
      "Likes:",
      "Neutrals:",
      "Dislikes:",
