  const TIMELINE_TITLE = settings.TIMELINE_TITLE;
  const COUNTDOWNS_TITLE = settings.COUNTDOWNS_TITLE;
  const TIMELINE_BUCKETS = [
    { name: "Night", at: 0.92 }, { name: "Dawn", at: 0.23 }, { name: "Morning", at: 0.35 },
    { name: "Midday", at: 0.5 }, { name: "Afternoon", at: 0.63 }, { name: "Evening", at: 0.79 }
