  const TIMELINE_VAGUE_NUM = "(a few|few|several|some|many)";
  const TIMELINE_UNIT = "(minute|hour|day|night|week|month|year)s?";
  const TIMELINE_UNIT_DAYS = { minute: 1 / 1440, hour: 1 / 24, day: 1, night: 1, week: 7, month: 30, year: 365 };
  const TIMELINE_FLASH_FORWARD = /\b(?:will|won['’]t|would|['’]ll|might|could|should|must|going to|gonna|someday|one day)\b/i;
  // Mid-sentence cues only count in plain narration: not plans, conditions,
  // recollections or reported speech ("he said he'd be back the next morning").
  const TIMELINE_NOT_ELAPSED = /\b(?:will|won['’]t|would|['’]ll|\w+['’]d|might|could|should|must|going to|gonna|plan(?:s|ned|ning)?|promis\w*|intend\w*|hop(?:e|es|ed|ing)|if|unless|tomorrow|someday|ago|remember\w*|recall\w*|used to|had\s+(?:been|passed|gone|spent)|said|says|told|tells|ask(?:s|ed)|explain\w*|mention\w*|agree\w*|suggest\w*|warn\w*)\b/i;

  function blankTimeline() {
    return {
      schema: 1, now: 0.375, todKnown: false, dayOffset: 0,
