      schema: 1,
      now: Math.max(0, finiteOr(source.now, base.now)),
      todKnown: source.todKnown === true,
      dayOffset: Math.round(finiteOr(source.dayOffset, 0)),
      dateBase: source.dateBase === null || source.dateBase === undefined ? null : Math.round(finiteOr(source.dateBase, 0)),
