      weekdayBase: source.weekdayBase === null || source.weekdayBase === undefined ? null : ((Math.round(finiteOr(source.weekdayBase, 0)) % 7) + 7) % 7,
      yearDayBase: source.yearDayBase === null || source.yearDayBase === undefined ? null : Math.round(finiteOr(source.yearDayBase, 0)),
      yearPrecision: ["month", "season"].includes(source.yearPrecision) ? source.yearPrecision : "",
      events: (Array.isArray(source.events) ? source.events : []).filter(item => item && typeof item === "object").slice(0, 60).map(item => ({
