    if (/\b(?:noon|midday|lunchtime|lunch)\b/.test(text)) return "Midday";
    if (/\bafternoon\b/.test(text)) return "Afternoon";
    if (/\b(?:evening|dusk|sunset|twilight|nightfall)\b/.test(text)) return "Evening";
