  }

  // A clock time such as "3 pm" or "15:30" as a fraction of the day.
  function timelineClockFraction(value) {
    const match = textOf(value).match(/\b(\d{1,2})(?::(\d{2}))?\s*(a\.?m\.?|p\.?m\.?)?(?![\w:])/i);
    if (!match || (!match[2] && !match[3])) return null;
    let hours = Number(match[1]);
    const minutes = Number(match[2] || 0);
    const meridiem = keyOf(match[3] || "").replace(/\s+/g, "");
    if (meridiem.startsWith("p") && hours < 12) hours += 12;
    if (meridiem.startsWith("a") && hours === 12) hours = 0;
