  function timelineSeasonOf(yearDay) {
    const day = ((yearDay % 365) + 365) % 365;
    // Month-based seasons: March-May spring, June-August summer, and so on.
    const seasons = [
      { name: "spring", start: 59, length: 92 }, { name: "summer", start: 151, length: 92 },
      { name: "autumn", start: 243, length: 91 }, { name: "winter", start: 334, length: 90 }
