  function restoreSnapshot(snapshot, expectedSceneEntry) {
    if (!snapshot || typeof snapshot !== "object") return false;
    [
      "npcs", "inputCount", "visibleGenerationCount", "stateClock", "lastCompletedActionCount",
      "openingSeen", "openingEvidenceId", "lastInput", "lastInputSignature",
      "focusLastServed", "sceneLastSeen", "recoveryPending", "sharedMoments",
      "activeKeys", "modelActiveKeys", "focusKey", "conversationKey", "evidence", "nextEvidenceNumber",
      "ownerOpportunities", "recoveringViews", "provenance", "operationState", "development", "lastTimeJumpEvidenceId",
      "timeline"
    ].forEach(field => { if (snapshot[field] !== undefined) CC[field] = clone(snapshot[field]); });
    CC.timeline = normalizeTimeline(CC.timeline);
    if (snapshot.lastGenuineOperation !== undefined) {
