    }
    ["lastName", "lastRelationship", "relationshipChange", "lastTurningPoint", "turningPointChange"]
      .forEach(field => {
        if (snapshot[field] !== undefined) CC.last[field] = line(snapshot[field], 700) || "None";
      });
    if (snapshot.lastProvenanceCreated !== undefined) {
      CC.last.provenanceCreated = line(snapshot.lastProvenanceCreated, 500) || "None";
    }
    if (snapshot.provenanceDiagnostics !== undefined) {
