    if (snapshot.cardHashes !== undefined) CC.cardHashes = clone(snapshot.cardHashes);
    const sceneCommittedEntry = expectedSceneEntry === undefined
      ? CC.sceneRecognition.lastCommittedEntry : expectedSceneEntry;
    let cardsRestored = restoreSceneCard(snapshot.sceneCard, sceneCommittedEntry);
    if (snapshot.sceneRecognition !== undefined) CC.sceneRecognition = normalizeSceneRecognition(snapshot.sceneRecognition);
    else if (runtime.sceneRecognition) CC.sceneRecognition.needsReassessment = true;
    if (snapshot.managedStateCards !== undefined) {
      cardsRestored = restoreManagedStateCards(snapshot.managedStateCards) && cardsRestored;
    }
    if (snapshot.managedDevelopmentCards !== undefined) {
      cardsRestored = restoreManagedDevelopmentCards(snapshot.managedDevelopmentCards) && cardsRestored;
    }
    if (snapshot.managedViewsCards !== undefined) {
      cardsRestored = restoreManagedViewsCards(snapshot.managedViewsCards) && cardsRestored;
    }
    if (snapshot.managedNamesCards !== undefined) {
      cardsRestored = restoreManagedNamesCards(snapshot.managedNamesCards) && cardsRestored;
    }
    if (snapshot.managedRelationshipsCards !== undefined) {
      cardsRestored = restoreManagedRelationshipsCards(snapshot.managedRelationshipsCards) && cardsRestored;
    }
    if (snapshot.managedTurningPointsCards !== undefined) {
      cardsRestored = restoreManagedTurningPointsCards(snapshot.managedTurningPointsCards) && cardsRestored;
    }
    if (snapshot.managedExperienceCards !== undefined) {
      cardsRestored = restoreManagedExperienceCards(snapshot.managedExperienceCards) && cardsRestored;
    }
    characters.forEach(character => {
      if (!CC.npcs[character.key]) CC.npcs[character.key] = blankNpc(character.startingStatus);
      else CC.npcs[character.key] = normalizeNpc(CC.npcs[character.key], character.startingStatus);
    });
    CC.evidence = (Array.isArray(CC.evidence) ? CC.evidence : []).map(normalizeEvidenceItem).filter(item => item.id && item.text);
    CC.provenance = normalizeProvenanceLedger(CC.provenance);
    CC.operationState = normalizeOperationState(CC.operationState);
    characters.forEach(character => {
      if (!CC.operationState.owners[character.key]) CC.operationState.owners[character.key] = blankOwnerOperationState();
    });
    return cardsRestored;
  }

  function restoreDiscardedGeneration() {
    const restored = restoreUndoSnapshot(CC.preGenerationSnapshot,
      undoExpectedCardsForPlan(CC.currentPlan)).ok;
    CC.lastVisibleOutputAnchor = null;
    return restored;
  }

  function frozenOperationSelectionFrom(plan) {
    const source = plan && typeof plan === "object" && !Array.isArray(plan) ? plan : {};
    if (source.settingTurn === true) return {
      settingTurn: true, sceneRequest: clone(source.sceneRequest)
    };
    if (source.operationSelectionFrozen !== true) return {};
    return {
      operationSelectionFrozen: true,
      operationScheduler: line(source.operationScheduler, 80),
      semanticAssessment: source.semanticAssessment === true,
      selectedOperationKind: line(source.selectedOperationKind, 40),
      selectedCandidate: clone(source.selectedCandidate),
      experienceChoices: clone(Array.isArray(source.experienceChoices) ? source.experienceChoices : []),
      assessmentRelationshipBaselines: clone(Array.isArray(source.assessmentRelationshipBaselines)
        ? source.assessmentRelationshipBaselines : []),
      operationCandidates: clone(Array.isArray(source.operationCandidates) ? source.operationCandidates : []),
      selectedEvidenceSignature: line(source.selectedEvidenceSignature, 500),
      selectedGain: Math.max(0, Math.floor(Number(source.selectedGain) || 0)),
      selectedDrain: Math.max(0, Math.floor(Number(source.selectedDrain) || 0)),
      selectedNet: Math.floor(Number(source.selectedNet) || 0),
      selectionReasons: clone(Array.isArray(source.selectionReasons) ? source.selectionReasons : []),
      operationTieBreak: line(source.operationTieBreak, 500)
    };
  }

  function pendingOperationRetryFromPlan(plan) {
    const source = plan && typeof plan === "object" && !Array.isArray(plan) ? plan : null;
    if (!source || source.taskDelivered !== true || source.task !== "operation"
      || !TASK_OPERATION_KINDS.includes(keyOf(source.selectedOperationKind))
      || !line(source.selectedEvidenceSignature, 500)) return blankPendingOperationRetry();
    const pendingPlan = {
      task: "operation",
      taskDelivered: true,
      ownerKey: source.ownerKey,
      focusKey: source.focusKey,
      activeKeys: clone(source.activeKeys || []),
      targets: clone(source.targets || []),
      evidenceIds: clone(source.evidenceIds || []),
      evidenceEligibility: clone(source.evidenceEligibility || {}),
      sourcePacket: clone(source.sourcePacket || []),
      sourcePacketText: "",
      operationTaskText: "",
      operationTaskKind: line(source.operationTaskKind, 40),
      relationshipPace: clone(source.relationshipPace || runtime.relationshipPace),
      genuineInputCount: Math.max(0, Math.floor(Number(source.genuineInputCount) || Number(CC.inputCount) || 0)),
      ...frozenOperationSelectionFrom(source)
    };
    return normalizePendingOperationRetry({
      active: true,
      sourceInputCount: pendingPlan.genuineInputCount,
      sourceActionCount: Number.isFinite(Number(source.actionCount))
        ? Math.max(0, Math.floor(Number(source.actionCount)))
        : -1,
      sourceKind: line(source.kind, 40),
      ownerKey: source.ownerKey,
      plan: pendingPlan
    });
  }

  function applyPendingOperationRetry(plan, pending) {
    const target = plan && typeof plan === "object" && !Array.isArray(plan) ? plan : null;
    const stored = normalizePendingOperationRetry(pending);
    if (!target || !stored.active || !stored.plan) return false;
    const source = stored.plan;
    target.pendingOperationRetry = true;
    target.pendingRetrySourceInputCount = stored.sourceInputCount;
    target.pendingRetrySourceActionCount = stored.sourceActionCount;
    target.pendingRetrySourceKind = stored.sourceKind;
    target.retryFocusKey = source.ownerKey || source.focusKey || stored.ownerKey;
    target.retryActiveKeys = clone(source.activeKeys || []);
    target.retryTargets = clone(source.targets || []);
    target.retryEvidenceIds = clone(source.evidenceIds || []);
    target.retryEvidenceEligibility = clone(source.evidenceEligibility || {});
    target.retrySourcePacket = clone(source.sourcePacket || []);
    target.retrySourcePacketText = textOf(source.sourcePacketText);
    target.retryOperationTaskText = textOf(source.operationTaskText);
    target.retryOperationTaskKind = line(source.operationTaskKind, 40);
    target.relationshipPace = clone(source.relationshipPace || runtime.relationshipPace);
    Object.assign(target, frozenOperationSelectionFrom(source));
    if (target.selectedCandidate && typeof target.selectedCandidate === "object") {
      target.selectedCandidate.pendingRetry = true;
    }
    return target.operationSelectionFrozen === true;
  }

  function cancelPendingOperationRetry(plan) {
    CC.pendingOperationRetry = blankPendingOperationRetry();
    if (CC.preGenerationSnapshot && typeof CC.preGenerationSnapshot === "object") {
      CC.preGenerationSnapshot.pendingOperationRetry = blankPendingOperationRetry();
    }
    if (!plan || typeof plan !== "object" || Array.isArray(plan)) return;
    delete plan.pendingOperationRetry;
    delete plan.pendingRetrySourceInputCount;
    delete plan.pendingRetrySourceActionCount;
    delete plan.pendingRetrySourceKind;
    plan.retryFocusKey = "";
    plan.retryActiveKeys = [];
    plan.retryTargets = [];
    plan.retryEvidenceIds = [];
    plan.retryEvidenceEligibility = {};
    plan.retrySourcePacket = [];
    plan.retrySourcePacketText = "";
    plan.retryOperationTaskText = "";
    plan.retryOperationTaskKind = "";
    plan.operationSelectionFrozen = false;
    plan.semanticAssessment = false;
    delete plan.semanticAssessmentResolved;
    plan.selectedOperationKind = "";
    plan.selectedCandidate = null;
    plan.operationCandidates = [];
    plan.selectedEvidenceSignature = "";
    plan.selectedGain = 0;
    plan.selectedDrain = 0;
    plan.selectedNet = 0;
    plan.selectionReasons = [];
    plan.operationTieBreak = "";
    plan.relationshipPace = clone(runtime.relationshipPace);
  }

  function pendingOperationRetryStillEligible(plan) {
    if (!plan || plan.pendingOperationRetry !== true) return false;
    const owner = characters.find(character => character.key === plan.retryFocusKey) || null;
    const kind = keyOf(plan.selectedOperationKind);
    const ids = unique(Array.isArray(plan.retryEvidenceIds) ? plan.retryEvidenceIds : [], 40);
    if (!sceneCharacterEligible(owner) || !TASK_OPERATION_KINDS.includes(kind) || !ids.length) return false;
    if (kind === ASSESSMENT_OPERATION_KIND) {
      const frozen = plan.retryEvidenceEligibility && typeof plan.retryEvidenceEligibility === "object"
        ? plan.retryEvidenceEligibility
        : {};
      const derived = relationshipDerivedEvidenceCandidates(owner, plan.retryTargets, null, plan.retrySourcePacket);
      return ids.every(id => {
        const eligibility = frozen[id];
        if (/^[SX]\d+$/.test(id)) {
          return !!(eligibility && eligibility.relationship && derived.some(source => source.item.id === id));
        }
        const item = evidenceForId(id);
        return !!(item && /^E\d+$/.test(id) && eligibility
          && ["name", "state", "relationship", "view", "turning"].some(field => eligibility[field] === true)
          && !(item.assessedNoChangeBy && item.assessedNoChangeBy[owner.key]));
      });
    }
    const rawIds = ids.filter(id => /^E\d+$/.test(id));
    if (rawIds.length) {
      const currentOpportunity = Math.max(0, Number(CC.ownerOpportunities[owner.key]) || 0);
      for (const id of rawIds) {
        const item = evidenceForId(id);
        if (!item) return false;
        if (kind === "state" && !stateEvidenceEligible(item, owner, "")) return false;
        if (kind === "name" && !nameEvidenceEligible(item, owner, "", "", "", currentOpportunity)) return false;
        if (kind === "relationship"
          && !relationshipEvidenceEligible(item, owner, "", "", currentOpportunity)) return false;
        if (kind === "view" && !viewEvidenceEligible(item, owner, "", "", currentOpportunity)) return false;
        if (kind === "turning" && !turningPointEvidenceEligible(item, owner, "", "", currentOpportunity)) return false;
      }
    }
    const derivedIds = ids.filter(id => /^[SRXV]\d+$/.test(id));
    if (kind === "relationship" && derivedIds.some(id => {
      const record = provenanceRecordById(id);
      return !relationshipDerivedRecordValid(record)
        || relationshipEventFieldReviewed(record, plan.selectedCandidate && plan.selectedCandidate.field);
    })) return false;
    if (kind === "relationship" && derivedIds.some((id, index) => derivedIds.slice(0, index)
      .some(otherId => sameAcceptedRelationshipEvent(provenanceRecordById(id), provenanceRecordById(otherId))))) return false;
    if (kind === "view" && plan.selectedCandidate && plan.selectedCandidate.operationReview === true
      && derivedIds.some(id => ordinaryViewEvidenceReviewed(provenanceRecordById(id)))) return false;
    if (derivedIds.length) {
      const frozenPacket = Array.isArray(plan.retrySourcePacket) ? plan.retrySourcePacket : [];
      if (derivedIds.some(id => !frozenPacket.some(source => source && source.id === id))) return false;
    }
    const frozenPacketCandidates = pendingRetryPacketCandidates(plan, kind);
    return !!modelAnswerTaskForCandidate(
      owner,
      plan.retryTargets,
      frozenPacketCandidates,
      "",
      "",
      plan.relationshipPace || runtime.relationshipPace,
      plan.selectedCandidate,
      plan.retryEvidenceIds
    );
  }

  function updatePendingOperationRetry(plan, outcome) {
    if (!plan || plan.taskDelivered !== true || plan.task !== "operation") return;
    const normalizedOutcome = keyOf(outcome);
    if ((["cutoff", "omitted", "stale"].includes(normalizedOutcome)
      || (normalizedOutcome === "malformed" && (plan.semanticAssessment === true
        || plan.operationScheduler === "single-operation-1")))
      && plan.pendingOperationRetry !== true) {
      CC.pendingOperationRetry = pendingOperationRetryFromPlan(plan);
      return;
    }
    CC.pendingOperationRetry = blankPendingOperationRetry();
  }

  function beginGenuineOperationRecord(inputEvidence, actionCount = platformActionCount()) {
    const record = blankLastGenuineOperation();
    record.actionCount = actionCount === null ? -1 : actionCount;
    record.inputCount = Math.max(0, Number(CC.inputCount) || 0);
    record.inputEvidenceId = continuitySourceId(inputEvidence && inputEvidence.id);
    record.phase = "awaiting context";
    record.resolution = "Awaiting context";
    CC.lastGenuineOperation = record;
  }

  function genuineOperationRecordMatchesPlan(plan) {
    const source = plan && typeof plan === "object" && !Array.isArray(plan) ? plan : {};
    const record = normalizeLastGenuineOperation(CC.lastGenuineOperation);
    const actionCount = Number.isFinite(Number(source.actionCount))
      ? Math.max(0, Math.floor(Number(source.actionCount)))
      : -1;
    if (actionCount >= 0 && record.actionCount >= 0) return record.actionCount === actionCount;
    const inputCount = Math.max(0, Math.floor(Number(source.genuineInputCount) || Number(CC.inputCount) || 0));
    const inputEvidenceId = continuitySourceId(source.inputEvidenceId);
    return record.inputCount === inputCount
      && (!inputEvidenceId || !record.inputEvidenceId || record.inputEvidenceId === inputEvidenceId);
  }

  function ensureGenuineOperationRecordForPlan(plan) {
    if (!plan || plan.opening || plan.opportunity !== true) return null;
    if (!genuineOperationRecordMatchesPlan(plan)) {
      beginGenuineOperationRecord({ id: plan.inputEvidenceId }, Number.isFinite(Number(plan.actionCount))
        ? Math.max(0, Math.floor(Number(plan.actionCount)))
        : platformActionCount());
