    return CC.lastGenuineOperation;
  }

  function recordGenuineContextPlan(plan, deferredReason = "") {
    const record = ensureGenuineOperationRecordForPlan(plan);
    if (!record) return;
    const owner = characters.find(character => character.key === plan.ownerKey) || null;
    record.phase = plan.taskDelivered || plan.sceneTaskDelivered ? "awaiting output" : "context built";
    record.task = line(plan.task, 40) || "none";
    record.taskDelivered = plan.taskDelivered === true || plan.sceneTaskDelivered === true;
    record.ownerKey = normalizedTargetKey(plan.ownerKey);
    record.ownerName = plan.settingTurn ? "Setting" : (owner ? owner.name : "");
    record.operationKind = plan.settingTurn ? "scene" : keyOf(plan.selectedOperationKind);
    record.ownerOpportunity = Math.max(0, Math.floor(Number(plan.ownerOpportunity) || 0));
