    "yourselves", "player", "someone", "somebody", "something", "somewhere",
    "anyone", "anybody", "anything", "anywhere", "everyone", "everybody",
    "everything", "everywhere", "nobody", "nothing", "nowhere", "thing", "things",
    "try", "tries", "tried", "trying", "want", "wants", "wanted", "wanting",
    "get", "gets", "got", "gotten", "getting", "make", "makes", "made", "making",
    "say", "says", "said", "saying", "tell", "tells", "told", "telling",
    "look", "looks", "looked", "looking", "seem", "seems", "seemed", "seeming",
