  function buildContext() {
    resetLastForContext();
    const contextDelivery = beginContextDelivery(originalText);
    const commitContextSuffix = (instructionText, preparedContext = contextDelivery.baseText) => {
      return contextDelivery.commit(instructionText, preparedContext);
    };
    refreshViewsStore(false);
    refreshNamesStore();
    applyManagedNameForms();
    refreshRelationshipsStore();
    refreshTurningPointsStore();
    refreshExperiencesStore(false);
    const plan = beginContinueIfNeeded(originalText);
    if (adoptTimelineCardEdits() && CC.preGenerationSnapshot && plan && plan.completed !== true && plan.kind !== "preview") {
      CC.preGenerationSnapshot.timeline = clone(CC.timeline);
    }
    // Revalidate delivery on each Context, including settings changed mid-turn.
    plan.sceneTaskDelivered = false;
    if (!runtime.sceneRecognition) {
      plan.settingTurn = false;
      delete plan.sceneRequest;
    }
    if (plan.sceneRequest && plan.sceneRequest.castEnabled !== undefined
      && plan.sceneRequest.castEnabled !== runtime.sceneCast) delete plan.sceneRequest;
    // Reconcile retry/undo first, then finish accepted memories from that restored branch.
    // This is deterministic completion of prior State updates, not another model operation.
    if (!plan.opening) promotePendingExperienceEvents();
    // Enabling/increasing the cooldown can hold an already queued retry. Restore
    // its frozen selection before normal validity checks on a rebuilt Context;
    // the cooldown gate will defer delivery again while the wait remains active.
    if (plan.pendingOperationRetry === true && plan.operationCooldownRemaining > 0
      && CC.pendingOperationRetry.active) {
      applyPendingOperationRetry(plan, CC.pendingOperationRetry);
    }
    const observedActionCount = platformActionCount();
    if (plan.opportunity === true && !plan.retry && observedActionCount !== null) {
      plan.actionCount = observedActionCount;
    }
    if (!plan.relationshipPace || typeof plan.relationshipPace !== "object") {
      plan.relationshipPace = clone(runtime.relationshipPace);
    }
    const recent = recentStoryFromContext(originalText);
    const currentInput = plan.kind === "input" || plan.retry ? CC.lastInput : "";
    const source = [currentInput, recent].filter(Boolean).join("\n").slice(-16000);
    if (plan.opening) {
      plan.task = "none";
      plan.taskDelivered = false;
      plan.profileTaskDelivered = false;
      const openingCharacters = activeNpcRosterCharacters()
        .filter(character => developmentProfileFor(character));
      const request = makeRosterImportRequest(true, contextDelivery.baseText)
        || makeDevelopmentRequest(openingCharacters, true);
      plan.developmentRequest = request ? clone(request) : null;
      plan.profileTaskDelivered = false;
      plan.activeKeys = openingCharacters.map(character => character.key);
      if (!request) {
        CC.last.context = "Opening prompt retained; every roster NPC already has a complete pack or no compiler task is pending.";
        return commitContextSuffix("").text;
      }
      const appended = appendCompleteDevelopmentTask(contextDelivery.baseText, request);
      const committed = appended.ok
        ? commitContextSuffix(developmentContextSuffixInstruction(request), appended.text)
        : { ok: false, delivered: false, text: originalText, suffix: "" };
      const maximum = Number(typeof info !== "undefined" && info ? info.maxChars : 0) || 0;
      const withinMaximum = maximum <= 0 || committed.text.length <= maximum;
      const taskBeforeSuffix = committed.suffix
        ? committed.text.slice(0, committed.text.lastIndexOf(committed.suffix)).trimEnd()
        : committed.text.trimEnd();
      const taskVerified = taskBeforeSuffix.endsWith(appended.task.trimEnd());
      plan.profileTaskDelivered = committed.ok && committed.delivered && withinMaximum && taskVerified;
      if (!plan.profileTaskDelivered) {
        const restored = commitContextSuffix("", contextDelivery.baseText);
        plan.developmentRequest = null;
        CC.last.gracefulFallback = true;
        CC.last.context = "Opening prompt retained; source compilation was deferred because its complete packet did not fit.";
        return restored.ok ? restored.text : originalText;
      }
      CC.last.task = "profile";
      CC.last.owner = request.targets.map(target => target.name).join(", ");
      CC.last.context = request.kind === "import"
        ? "Opening prompt retained; its suppressed response is compiling one complete six-card draft from gathered source material."
        : "Opening prompt retained; its suppressed response is building one grounded profile detail for one progressive roster NPC.";
      return committed.text;
    }
    expireTemporaryState(CC.stateClock);
    if (!plan.retry && plan.inputEvidenceId && plan.inputEvidenceId !== CC.lastTimeJumpEvidenceId && sceneTimeJump(currentInput)) {
      resetSceneForTimeJump(plan.inputEvidenceId);
