    }
    // A possible cast change preempts a queued NPC retry on a new action.
    // Same-action retries keep their frozen request and restored scene baseline.
    if (!plan.retry && (!plan.operationSelectionFrozen || plan.pendingOperationRetry)) {
      plan.sceneCastReviewReason = sceneCastReviewReason(plan, contextDelivery.baseText);
      if (plan.sceneCastReviewReason && plan.pendingOperationRetry) cancelPendingOperationRetry(plan);
    }
    const queuedImportRequest = plan.sceneCastReviewReason ? null : makeRosterImportRequest(false, contextDelivery.baseText);
    let active = selectActive(source, currentInput, plan);
    if (plan.retry && Array.isArray(plan.retryActiveKeys) && plan.retryActiveKeys.length) {
      const repeated = plan.retryActiveKeys
        .map(key => characters.find(character => character.key === key))
        .filter(sceneCharacterEligible)
        .slice(0, runtime.maxActive);
      if (repeated.length) active = repeated;
    }
    let focus = selectFocus(active, currentInput);
    if (plan.pendingOperationRetry === true
      && (!focus || focus.key !== plan.retryFocusKey
        || !active.some(character => character.key === plan.retryFocusKey))) {
      cancelPendingOperationRetry(plan);
    }
    if (plan.pendingOperationRetry === true && !pendingOperationRetryStillEligible(plan)) {
      cancelPendingOperationRetry(plan);
      CC.last.warning = [CC.last.warning,
        "A queued operation retry was canceled because its frozen owner, evidence, or model-answer template was no longer valid; this action was rescored normally."
      ].filter(Boolean).join(" ");
    }
    if (plan.retry && plan.retryFocusKey) {
      const frozenFocus = active.find(character => character.key === plan.retryFocusKey)
        || characters.find(character => character.key === plan.retryFocusKey) || null;
      if (sceneCharacterEligible(frozenFocus)) {
        focus = frozenFocus;
        if (!active.some(character => character.key === frozenFocus.key)) {
          active = [frozenFocus].concat(active).slice(0, runtime.maxActive);
        }
      }
    }
    if (sceneTurnDue(plan, active, focus, queuedImportRequest)) {
      const sceneContext = buildSceneContext(contextDelivery.baseText, active, focus, plan, commitContextSuffix);
      if (sceneContext !== null) return sceneContext;
    }
    // The character the input is about stays in context as another active NPC
    // when someone else takes this update (recorded for diagnostics).
    const naturalFocus = selectFocus(active, currentInput);
    if (plan.operationSelectionFrozen === true && plan.turnTakerKey && !plan.retry && !plan.pendingOperationRetry) {
      const frozenTaker = active.find(character => character.key === plan.turnTakerKey);
      if (frozenTaker) focus = frozenTaker;
    } else {
      const turnTaker = otherParticipantTurn(plan, active, focus, currentInput, recent);
      plan.turnTakerKey = turnTaker ? turnTaker.key : "";
      if (turnTaker) focus = turnTaker;
    }
    plan.carriedFocusKey = naturalFocus && focus && naturalFocus.key !== focus.key ? naturalFocus.key : "";
    const focusDevelopment = developmentProfileFor(focus);
    const developmentDue = !!(
      plan.opportunity && !plan.pendingOperationRetry && !CC.recoveryPending
      && focusDevelopment
      && CC.visibleGenerationCount - focusDevelopment.lastServedGeneration
        >= settings.DEVELOPMENT_INTERVAL
    );
    plan.developmentRequest = queuedImportRequest || (developmentDue
      ? makeDevelopmentRequest([focus], false)
      : null);
    plan.profileTaskDelivered = false;
    if (!active.length || !focus) {
      CC.activeKeys = [];
      CC.modelActiveKeys = [];
      CC.focusKey = "";
      plan.activeKeys = [];
      plan.task = "none";
      plan.taskDelivered = false;
      if (plan.developmentRequest && plan.developmentRequest.kind === "import") {
        const appended = appendCompleteDevelopmentTask(contextDelivery.baseText, plan.developmentRequest);
        const committed = appended.ok
          ? commitContextSuffix(developmentContextSuffixInstruction(plan.developmentRequest), appended.text)
          : { ok: false, delivered: false, text: originalText, suffix: "" };
        const maximum = Number(typeof info !== "undefined" && info ? info.maxChars : 0) || 0;
        const withinMaximum = maximum <= 0 || committed.text.length <= maximum;
        const taskBeforeSuffix = committed.suffix
          ? committed.text.slice(0, committed.text.lastIndexOf(committed.suffix)).trimEnd()
          : committed.text.trimEnd();
        const taskVerified = taskBeforeSuffix.endsWith(appended.task.trimEnd());
        plan.profileTaskDelivered = committed.ok && committed.delivered && withinMaximum && taskVerified;
        if (plan.profileTaskDelivered) {
          CC.last.task = "profile";
          CC.last.owner = plan.developmentRequest.targets[0].name;
          CC.last.context = "No prepared CC character was active; one source-compiler section was requested alongside complete story prose.";
