    plan.profileTaskDelivered = attempt.profileTaskDelivered === true;
    plan.ownerKey = focus.key;
    plan.focusKey = focus.key;
    plan.targets = clone(attempt.targets || []);
    plan.evidenceIds = clone(attempt.evidenceIds || []);
    plan.operationTaskText = attempt.taskDelivered
      ? textOf(attempt.operationOnlyTaskText || attempt.taskText)
