    if (maintenanceSession.recorded) return;
    const loaded = STORE_KINDS.filter(kind => storeSession[kind].loaded);
    const repaired = unique(maintenanceSession.repaired, 40);
    const managedWrites = STORE_KINDS.reduce((total, kind) => total + storeSession[kind].writes, 0);
    if (contextHook) {
      CC.maintenance.schemaVersion = settings.MAINTENANCE_SCHEMA_VERSION;
      CC.maintenance.structureSignature = ownedStructureMaintenanceSignature();
      CC.maintenance.managedStoreSignature = managedStoreMaintenanceSignature();
      if (fullManagedMaintenanceRequired) CC.maintenance.fullRuns += 1;
      else CC.maintenance.reuseRuns += 1;
    } else {
      CC.maintenance.deferredRuns += 1;
      if (managedWrites > 0 && CC.maintenance.schemaVersion === settings.MAINTENANCE_SCHEMA_VERSION) {
        CC.maintenance.managedStoreSignature = managedStoreMaintenanceSignature();
      }
    }
    CC.maintenance.lastHook = hook;
    CC.maintenance.lastMode = maintenanceSession.mode;
    CC.maintenance.lastLoaded = loaded;
    CC.maintenance.lastRepaired = repaired;
    maintenanceSession.recorded = true;
